window.HARDTRP.receive("29484",[[29485,"2026-06-05T18:32:24",9,"Начало темы.\n\n@detahsola — Дм этой темы.",29484,null],[29486,"2026-06-05T18:33:31",64,"УАААААААА ПЕРВЫЙ КВЕСТ КАК ДМ\n\n\nЩас оформлю ребятки",29484,null],[29487,"2026-06-05T18:33:47",36,"//давай \nДвигай",29486,null],[29524,"2026-06-05T19:12:31",64,"🌸🌸🌸",29484,null],[29525,"2026-06-05T19:12:32",64,"Герои получили письмо от старейшины деревни «Далёкий Мост», письмо гласит: \"Здравствуйте достопочтенная гильдия приключенцев! Я - старейшина деревни «Далёкий Мост» хочу попросить у вас помощи! Видите ли, мой давний товарищ, по совместительству купец и бродячий торговец, основа нашей связи с внешним миром пропал уж неделю как! Нам нужна ваша помощь в его поиске, ибо с ним могло что то случится. Приезжайте в деревню, я вам все расскажу лично!\". Сейчас ваши герои перемещаются по лесу на юг, в сторону этой деревни пешком, идти не долго осталось, совсем скоро вы подойдёте к этой деревушке и ваше приключение начнётся. А пока, если вы считаете нужным, можете в рамках рп пообщаться и познакомиться друг с другом в свободной форме, если ваши герои были до этого не знакомы\n\n🔠 В общем, мини рп в свободное время и свободной форме на разогрев чисто между игроками пообщаться\n\n\nЭтакий мини-список эталонного поведения за столом во время этой игры, который, хотелось бы, чтоб вы соблюдали:\n\n🔠 Ответственность. Если вы освободили для игры время, то извольте явиться и играть когда вас ждут, нас и так мало, так что было бы неплохо чтобы да.\n\n🔠 Адекватность за столом. Безусловно, вы в праве делать все что душе вздумается, я вас не ограничиваю никак, но просто в голове держите любое действие имеет последствия\n\nСильно много не прошу, так что да, просто адекватность и пунктуальность, и, быть может, пощажу вас👹👹👹",29484,null],[29526,"2026-06-05T19:12:32",64,"Игроки и их персонажи:\n\n1. @Professor_3M653 — Кью (https://t.me/c/3239766844/954) \n2. @Jak_Zak — Жакио (https://t.me/c/3239766844/1390)\n3. @elsio28 — Бхагар (https://t.me/c/3239766844/1327)",29484,null],[29530,"2026-06-05T19:13:11",36,"//игра когда?",29526,null],[29531,"2026-06-05T19:14:14",64,"//а когда хотите? Могу хоть завтра ток не в ночь, ночью мне водить будут",29530,null],[29532,"2026-06-05T19:15:32",5,"//могу завтра с утра до полуночи",29484,null],[29534,"2026-06-05T19:15:46",64,"//ну вот",29532,null],[29536,"2026-06-05T19:16:21",36,"//могу сегодня",29531,null],[29537,"2026-06-05T19:16:25",36,"//до ночи",29484,null],[29538,"2026-06-05T19:16:35",64,"// @Professor_3M653 @Jak_Zak завтра в день, где то в часа 2 дня по мск норм? Там часа 3-4 мб посидим поиграем",29484,null],[29539,"2026-06-05T19:16:45",64,"//а мне достроить под вас бы сегодня",29536,null],[29540,"2026-06-05T19:16:59",36,"//неа, у меня завтра весь день занятия. Вообще не могу",29538,null],[29541,"2026-06-05T19:17:05",64,"//окау",29540,null],[29542,"2026-06-05T19:17:08",64,"//воскресенье?",29540,null],[29543,"2026-06-05T19:17:13",36,"Тоже занятя",29542,null],[29544,"2026-06-05T19:17:19",64,"//а когда",29543,null],[29546,"2026-06-05T19:17:24",36,"Понедельник только если после 14",29484,null],[29554,"2026-06-05T19:18:30",64,"@Professor_3M653 @Jak_Zak @elsio28 В понедельник к вечеру свободны?",29484,null],[29555,"2026-06-05T19:19:10",5,"скорее да, если у меня другой квест не будет в это время",29554,null],[29557,"2026-06-05T19:19:25",36,"Я уже сказала",29554,null],[29558,"2026-06-05T19:19:31",64,"Ну я тебя на это время бронирую",29555,null],[29559,"2026-06-05T19:19:39",36,"А бля...",29557,null],[29560,"2026-06-05T19:19:40",36,"Не",29484,null],[29561,"2026-06-05T19:19:45",36,"У меня вечером тоже занятия",29484,null],[29562,"2026-06-05T19:19:49",64,"Ебать а когда",29561,null],[29563,"2026-06-05T19:19:50",36,"Ебучие экзамены....",29484,null],[29564,"2026-06-05T19:19:52",36,"Лучше сегодня",29484,null],[29565,"2026-06-05T19:19:58",64,"Ммм",29564,null],[29566,"2026-06-05T19:20:05",64,"До какой ночи?",29484,null],[29567,"2026-06-05T19:20:12",36,"Иначе до четверга меня не встретите",29484,null],[29568,"2026-06-05T19:20:23",36,"Могу до 1 спокойно сидеть",29566,null],[29569,"2026-06-05T19:20:34",36,"Потом тяжелее но смогу сидеть",29568,null],[29570,"2026-06-05T19:20:38",64,"@Jak_Zak @elsio28 В сегодня же нахуй ночью отыграем?",29484,null],[29571,"2026-06-05T19:20:44",64,"Это по мск",29568,null],[29574,"2026-06-05T19:21:51",36,"Ага",29571,null],[29576,"2026-06-05T19:21:58",36,"У меня это 3 часа ночи",29484,null],[29577,"2026-06-05T19:22:38",64,"Ебать",29576,null],[29579,"2026-06-05T19:22:53",64,"Лан, прорвёмся надеюсь",29484,null],[29581,"2026-06-05T19:23:03",64,"Щас",29570,null],[29585,"2026-06-05T19:23:23",64,"Щас одну смог притащить там остальные не могут, одних смог другая не сможет",29484,null],[29586,"2026-06-05T19:23:25",64,"Мечта",29484,null],[29589,"2026-06-05T19:23:32",36,"Это база",29586,null],[29591,"2026-06-05T19:23:39",64,"Скотобаза",29589,null],[29593,"2026-06-05T19:24:04",64,"Лан надеюсь вы соберётесь и образцово за 1 сессию какой то молитвой пройдёте квест этот",29484,null],[29595,"2026-06-05T19:24:23",64,"В лучшем случае вас встретит 1 тварь финальная",29593,null],[29596,"2026-06-05T19:24:36",64,"В худшем вас на первой же локации могут убить",29484,null],[29600,"2026-06-05T19:27:12",36,"//можешь описать то откуда мы начинаем?",29596,null],[29602,"2026-06-05T19:27:32",36,"//хочу просто ещё с внешними факторами повзаимодействовать",29484,null],[29604,"2026-06-05T19:32:23",64,"//могу",29600,null],[29605,"2026-06-05T19:32:38",64,"//чуть позже",29484,null],[29615,"2026-06-05T19:41:05",5,"могу до 1 по мск",29568,null],[29617,"2026-06-05T19:41:28",36,"БРАТЮНЯЯЯ!!!\n\nОбняла",29615,null],[29619,"2026-06-05T19:42:09",64,"Сегодня типо?",29615,null],[29620,"2026-06-05T19:42:17",64,"У нас ласт тип значит будет щас",29484,null],[29628,"2026-06-05T19:48:31",64,"Щас сатану заспавним",29526,null],[29635,"2026-06-05T19:50:12",36,"Кью сидит (на чём то) и кушая мясо бубнит про себя слова. если прислушаться то можно услышать как она говорит \"Ярарара\", а так же записывает что то на листок бумаги в ожидании других",29484,null],[29640,"2026-06-05T19:52:41",36,"Кью была повором, шулером, детективом, охотником, грибником, следопытом, теперь она хочет попробовать себя в роли певца и композитора",29484,null],[29642,"2026-06-05T19:56:10",64,"//явно подходящий квест для, ну окей, интересно как",29640,null],[29643,"2026-06-05T19:56:37",64,"//щас у меня 1 локу дополнить осталось более детальное описание кину вашей стоянки условной",29484,null],[29644,"2026-06-05T19:56:48",36,"//что как? она просто сидит и пишет что та на листочке\nэто внеигровой прикол что делает моего персонажа более живым",29642,null],[29647,"2026-06-05T19:58:17",64,"//окей понял, я в плане просто за процессом смотреть там",29644,null],[29648,"2026-06-05T19:58:34",36,"//а... Ну ты опиши и я опишу",29647,null],[29650,"2026-06-05T19:59:04",36,"//думаю те кто слушают японское творчество знают её",29635,null],[29654,"2026-06-05T20:03:49",36,"//я про песню",29650,null],[29656,"2026-06-05T20:05:30",64,"Герои шли по лесу в сторону деревни, на юг, вниз с более горных местностей. Вы остановись возле тропики на небольшой опушке леса перевести дух. Довольно тихое и спокойное место, единственные звуки которые вы слышите это редкое пение птиц и ветер, лёгкий, едва заметный ветер. Вокруг пахнет свежестью и немного сыростью, весьма обычно для этого места, до дороги рукой подать, на этом месте часто отдыхают путешествиники, это можно заметить по чуть прижатой траве, от частой ходьбы и нахождении на ней. Идти ещё около полу часа, но вы решили передохнуть",29600,null],[29663,"2026-06-05T20:09:16",36,"Кью сидела на камне припевая фразу и записывая на листочке, что лежал на коре дерева что-то",29656,null],[29665,"2026-06-05T20:13:02",64,"@Professor_3M653 @elsio28 @Jak_Zak к 10 вечера по Москве сможете собраться?",29484,null],[29666,"2026-06-05T20:13:08",64,"//ну пусть так",29484,null],[29670,"2026-06-05T20:17:20",36,"//угу",29665,null],[29703,"2026-06-05T21:02:06",5,"//lf",29665,null],[29704,"2026-06-05T21:02:11",5,"// да",29484,null],[29708,"2026-06-05T21:05:13",64,"//львы тигры молодцы ребятки, а где ЖакаЗака 😳😳😳",29484,null],[29711,"2026-06-05T21:07:01",36,"А вот он ХЫЗЗЫ",29708,null],[29712,"2026-06-05T21:07:09",36,"звоните ему хулэ",29484,null],[29717,"2026-06-05T21:19:27",36,"@detahsola \n@elsio28 \n@Jak_Zak \nЯ ЕГО РАЗБУДИЛА!!!!!!!!!!\nПОШЛИ ИГЛАТЬ!",29484,null],[29718,"2026-06-05T21:19:36",64,"Я тоже",29717,null],[29719,"2026-06-05T21:19:38",64,"Щас",29484,null],[29720,"2026-06-05T21:19:44",64,"Минут 40 ещё",29484,null],[29721,"2026-06-05T21:19:49",64,"Мне доделать вам надо вверху",29484,null],[29722,"2026-06-05T21:19:52",64,"Сверху *",29484,null],[29723,"2026-06-05T21:19:54",36,"//ЭХХХ",29720,null],[29735,"2026-06-05T21:30:01",42,"// ывывы",29484,null],[29736,"2026-06-05T21:30:46",42,"// кстати надеюсь вы ознакомились с Жакио, хотя бы с его навыками. А то вопросики могут появитьсч",29484,null],[29738,"2026-06-05T21:31:11",36,"//у меня нет, ибо мине поху\nа вот ДМ должно было",29736,null],[29741,"2026-06-05T21:31:27",36,"//а ещё... не совсем поху, просто это не интересна",29484,null],[29745,"2026-06-05T21:32:55",42,"// ок, кровавый охотник весело и больно",29484,null],[29746,"2026-06-05T21:33:22",64,"//почему я блять средний род",29738,null],[29747,"2026-06-05T21:34:41",64,"//ну ниче, если не пойму спрошу как работает",29736,null],[29748,"2026-06-05T21:35:29",64,"//бля почему я не заметил что хб щас этот класс который ещё дай бог раза 2 встречу заучивать👀",29484,null],[29749,"2026-06-05T21:36:43",36,"//да не учи\nпросто спроси когда не поймешь что именноо он сделал и усё",29748,null],[29750,"2026-06-05T21:40:45",5,"// да пофиг",29736,null],[29751,"2026-06-05T21:42:28",42,"// класс для БДСМщиков",29484,null],[29752,"2026-06-05T21:43:50",64,"//я с вами настрадаюсь",29751,null],[29753,"2026-06-05T21:44:12",64,"//можете тут остановитьься поиграть друг с другом, пороллить",29656,null],[29754,"2026-06-05T21:44:19",64,"//если хотите",29484,null],[29755,"2026-06-05T21:45:25",64,"//бля ещё в закрытую бы кубы кидать",29484,null],[29756,"2026-06-05T21:51:53",5,"// зачем взакрытую?",29755,null],[29757,"2026-06-05T21:53:11",64,"//чтоб вы не знали, ебака убила союзника и его можно оживить или он уже у проотцов",29756,null],[29758,"2026-06-05T21:53:26",64,"//я не буду расслабтесь",29484,null],[29759,"2026-06-05T21:54:06",64,"1. @Professor_3M653 — Кью (https://t.me/c/3239766844/954) \n2. @Jak_Zak — Жакио (https://t.me/c/3239766844/1390)\n3. @elsio28 — Бхагар (https://t.me/c/3239766844/1327)\n\nГайс 5 минуточек до начала",29484,null],[29760,"2026-06-05T21:55:15",42,"//да так будет лучше, способок не много и \"каноничны\" Его создателем + балансен очень",29749,null],[29761,"2026-06-05T21:59:59",5,"Крепкий минотавр осмотрел своих спутников.\n\nДевочка? На опасном задании? Что-то с ней не так. Нельзя ей доверять, решил Бхагар.",29484,null],[29762,"2026-06-05T22:00:56",5,"Тифлинг выглядел необычно, но хотя бы по-боевому. К нему больше доверияю",29484,null],[29763,"2026-06-05T22:01:51",5,"Минотавр решил представиться первым.\n\n— Бхагар!",29484,null],[29764,"2026-06-05T22:03:27",5,"// где вы",29484,null],[29765,"2026-06-05T22:04:33",64,"Герои выходят к деревне, деревня представляет из себя несколько домиков с участками вокруг колодца, расположенная у моста, идущего через небольшую реку, возможно, от сюда и название. Пройдя чуть ближе к центру, они замечают несколько домов с надписями на странном диалекте общего, либо написанные очень кривым почерком. Они видят самый большой дом здесь, возможно это дом старейшины. Герои, что вы делаете?",29484,null],[29766,"2026-06-05T22:04:45",64,"// @Jak_Zak @Professor_3M653 гайс вы тут?",29484,null],[29767,"2026-06-05T22:05:25",64,"//ясно🚬🚬🚬🚬",29484,null],[29768,"2026-06-05T22:05:44",5,"— Дом старейшины! Нам определённо надо поговорить с ним и узнать детали задания.",29484,null],[29769,"2026-06-05T22:06:22",5,"// опаздывающие игроки никогда не меняются",29484,null],[29770,"2026-06-05T22:06:32",64,"//окей я вроде говорил на счёт пунктуальности, пока с тобой поиграем 😊",29768,null],[29771,"2026-06-05T22:06:55",5,"// ок только не убивай меня пока я один",29484,null],[29772,"2026-06-05T22:07:09",42,"// я тута",29484,null],[29773,"2026-06-05T22:07:12",64,"//о",29772,null],[29774,"2026-06-05T22:07:22",64,"//просыпаются",29484,null],[29775,"2026-06-05T22:07:32",42,"// сорянчик коктели дедал и бутеры",29484,null],[29776,"2026-06-05T22:07:55",5,"Минотавр набирает воздух в лёгкие и громогласно кричит.\n\n— Старейшина, выходи! Пришли герои искать купца!",29484,null],[29777,"2026-06-05T22:09:06",64,"но в ответ тишина... Работяги в деревне работают на поле, слышен удар молота в кузне и сплетни женщин у скамейки. Но старейшины не слышно. Где же он?",29776,null],[29778,"2026-06-05T22:09:42",5,"— Раз не отвечает, значит не в доме. Надо поговорить с местными.",29484,null],[29779,"2026-06-05T22:10:15",5,"Минотавр подходит к женщинам на скамейке, стараясь никого не напугать",29484,null],[29780,"2026-06-05T22:12:38",5,"— Приветствую, дамы! Не подскажите, куда ваш староста подевался?",29484,null],[29781,"2026-06-05T22:13:15",64,"женщина по старше, чуть поседевшая, но не старая, выхватывает из за пазухи аммулет с каким то языческим божеством и говорит\n—ой багря багря багря, Багаролорд помилуй! Ушёл он, на охоту, там вон, на дверце его записку оставил!",29780,null],[29782,"2026-06-05T22:13:40",64,"женщина указывает на большой дом",29484,null],[29783,"2026-06-05T22:14:16",5,"— Спасибо, сейчас прочту\n\n*возвращаюсь к двери и беру записку*",29484,null],[29784,"2026-06-05T22:14:25",5,"Что же там написано?",29484,null],[29785,"2026-06-05T22:14:31",44,"//  я победил",29778,null],[29786,"2026-06-05T22:15:33",5,"// теперь победи проблему непришедших игроков",29785,null],[29787,"2026-06-05T22:15:43",36,"//я писала артефакт мифической редкости\nесли хотите потом покажу этот пиздец для ДМов и игроков",29766,null],[29788,"2026-06-05T22:16:32",36,"//я прочитала как тупица",29776,null],[29789,"2026-06-05T22:16:49",64,"записка приколочена кинжалом, на ней написано\n«ушёл на охоту, приду через неделю. —Сэр Гердрих»\nснизу ещё одна записка. Читаешь?",29783,null],[29790,"2026-06-05T22:17:00",44,"// ну это невозможно",29786,null],[29791,"2026-06-05T22:17:13",5,"*читаю*",29789,null],[29792,"2026-06-05T22:17:49",5,"— Через неделю!? Что за нравы, пишут письма о помощи, а сами исчезают, — Бхагар возмущён",29484,null],[29793,"2026-06-05T22:18:26",36,"Кью стоит от всех по отдаль глядя на мужиков в поле. Смотрела она на них заварожёно, слово то гигантские с гору ходячие каменные големы",29484,null],[29794,"2026-06-05T22:19:13",42,"// дуратский интернет",29484,null],[29795,"2026-06-05T22:19:24",42,"// надеюсь в последний раз пропадает",29484,null],[29796,"2026-06-05T22:22:04",5,"// ты что-то пишешь?",29484,null],[29797,"2026-06-05T22:23:24",36,"//все здесь, но стоят",29796,null],[29798,"2026-06-05T22:23:27",36,"//кааайф",29484,null],[29799,"2026-06-05T22:23:36",64,"Ты срываешь записку с двери, что то металлическое падает на землю. Записка гласит:...\n“ЧИТАТЬ ЕСЛИ ВЫ С ГИЛЬДИИ РЕШАТЬ ПРОБЛЕМУ С КУПЦОМ”\n«Здравствуйте путники! Сожалею что не встретил вас лично, неотложные планы! Я отправлял в город письмо с жалобой, но нам ответили что Малсера отправили и он дошёл до нескольких деревень! Я не понимаю где он мог потеряться, надо всю дорогу, весь его путь осмотреть и понять где он. Сейчас, отправляйтесь на юг, в сторону моста, с обратной стороны от места откуда вы пришли. Вам нужно посетить его предыдущий пункт, деревню \"Скреб\", может там его видели? Просто езжайте в лес и там со временем выедете в поле, а от туда рукой подать до Скреба, если в пол день выдвинетесь то к вечеру доедете!»\nСнизу, мелким шрифтом: \"можете взять моих лошадей, там 4 лошадки, возьмите сколько нужно и езжайте, ключ прикрепил, надеюсь он там. И прошу, найдите Малсера, вы наша последняя надежда!\"",29791,null],[29800,"2026-06-05T22:25:00",5,"Минотавр читает письмо, но вскоре путается в тексте. Он качает головой и всучивает записку тифлингу.",29484,null],[29801,"2026-06-05T22:25:19",64,"//самый умный",29800,null],[29802,"2026-06-05T22:25:24",5,"— Я понял, что надо идти на юг. Остальное на вас",29484,null],[29803,"2026-06-05T22:25:50",64,"// и в реку шагнул",29802,null],[29804,"2026-06-05T22:25:53",36,"Кью замечает что у них какие-то тёрки и подходит к ним моргая глазками\n\n- Что у вас тут?",29800,null],[29805,"2026-06-05T22:26:15",5,"// письмо у тифли, можешь забрать пока он афк",29484,null],[29806,"2026-06-05T22:26:26",36,"//Ни кому?\nжал....",29787,null],[29807,"2026-06-05T22:26:37",5,"— Письмо непонятное...",29484,null],[29808,"2026-06-05T22:26:38",36,"//Оке",29805,null],[29809,"2026-06-05T22:26:44",5,"// мы поиграть хотим",29484,null],[29810,"2026-06-05T22:26:50",64,"//ну скинь ладно",29806,null],[29811,"2026-06-05T22:27:40",36,"Тифлинг не смог взять письмо так как завтыкал на прекрасных деревенских женщин что сидели на лавочке, поэтому записка упала. Кью подняла её и прочитала\n\n- Ага... Ключик! Ты видел ключик?",29800,null],[29812,"2026-06-05T22:28:01",5,"— Какой ключик? — минотавр ничего не понимает",29484,null],[29813,"2026-06-05T22:28:39",64,"ключ снизу, он выпал когда вы сорвали записку",29484,null],[29814,"2026-06-05T22:29:05",36,"Кью почесала голову и заметила ключ под ногами\n\n- Вот этот...\n\nОна подняла его, а после пошла за дом в поисках конницы с лошадками",29812,null],[29815,"2026-06-05T22:29:40",5,"— А, ключик, ага. Мы поедем на лошадях?",29484,null],[29816,"2026-06-05T22:30:07",36,"- Так быстрее чем пешком, или ты не умеешь кататься на них?",29815,null],[29817,"2026-06-05T22:30:55",5,"— Умею. Я немало проездил на боевых конях, когда воевал в степях родной земли, — гордо рассказывает Бхагар",29484,null],[29818,"2026-06-05T22:31:35",36,"Кью пропустила всё мимо ушей пока открывала конницу и выбирала лошадь\n\n- Ого...",29817,null],[29819,"2026-06-05T22:31:43",5,"— Не уверен, что здешние лошади потянут мой вес...",29484,null],[29820,"2026-06-05T22:31:59",64,"вот и она, небольшой домик-конюшня и 4 ездовые, уже снаряженные лошади. У каждой есть седло, можно садиться и ехать хоть щас, только вывести из конюшни",29814,null],[29821,"2026-06-05T22:32:21",5,"*выбираю самую крупную и сильную из лошадей и вывожу на улицу*",29484,null],[29822,"2026-06-05T22:32:30",36,"Кью посмотрела на тебя, затем на лошадок\n\n- Да.... Тебе видимо прийдётся пешком",29819,null],[29823,"2026-06-05T22:32:47",5,"— Сейчас попробуем.\n\n*седлаю лошадь*",29484,null],[29824,"2026-06-05T22:33:09",64,"//брад 480 фунтов",29819,null],[29825,"2026-06-05T22:34:08",5,"// кто? я полегче",29824,null],[29826,"2026-06-05T22:34:15",64,"ты седлаешь и садишься на лошадь, кажется, ей едва комфортно с тобой ехать, но она держит твой вес. Вроде бы нормально",29823,null],[29827,"2026-06-05T22:34:21",64,"//она держит столько",29825,null],[29828,"2026-06-05T22:34:38",5,"// норм",29827,null],[29829,"2026-06-05T22:35:08",5,"— Может, возьмём запасную? Мало ли что случится в дороге",29826,null],[29830,"2026-06-05T22:35:29",64,"//нормально тип на двух лошадях едет",29829,null],[29831,"2026-06-05T22:35:50",64,"//давай не, я ее из боевых сцен вычеркнул уже и как то ме добавлять",29484,null],[29832,"2026-06-05T22:35:53",5,"// за поводья вести пока скачешь",29830,null],[29833,"2026-06-05T22:35:59",5,"// ок(",29831,null],[29834,"2026-06-05T22:36:12",64,"//все",29484,null],[29835,"2026-06-05T22:36:28",64,"лошади у вас, герои, что вы делаете?",29484,null],[29836,"2026-06-05T22:36:47",5,"— Направляемся на юг, к мосту!",29484,null],[29837,"2026-06-05T22:37:13",5,"Поскольку минотавр плохо ориентировался, куда ехать, он занял место в конце строя",29484,null],[29838,"2026-06-05T22:37:34",64,"//рахмет что напомнил",29484,null],[29839,"2026-06-05T22:37:43",64,"//щас вы выедете я спрошу",29484,null],[29840,"2026-06-05T22:37:51",36,"Сижу на лошадке, лошадке очень легко. Кью лёгкая. Кью нравится лошадка, она гладит её гриву и кормит травкой",29835,null],[29841,"2026-06-05T22:38:30",36,"Кью кивнула и направила всех на юг. Удобно когда у тебя вживлённый компас",29836,null],[29842,"2026-06-05T22:38:39",64,"// а где ваш третий медвежонок?",29484,null],[29843,"2026-06-05T22:38:46",64,"//три поросенка",29484,null],[29844,"2026-06-05T22:38:55",5,"// едет с нами, но без интернета",29842,null],[29845,"2026-06-05T22:38:55",64,"@Jak_Zak брад",29484,null],[29846,"2026-06-05T22:39:18",64,"//ты первая будешь значит",29841,null],[29848,"2026-06-05T22:40:42",5,"// я замыкаю или неважно",29846,null],[29851,"2026-06-05T22:42:03",64,"Герои выдвигаются по мосту на юг, в сторону деревни Скреб. Эта дорога по лесу выдаётся реально довольно длинной и нудной, почти весь путь занимает лес, почти весь день на ногах, как бы не выдохнутся? Герои проезжают лес, довольно быстро мелькают деревья и движется дорога под вами, ветер ласкает волосы (у кого что вместо них, нелюди). Быть может, ваши герои, чтоб скоротать ожидание, как то развлекут себя в пути?",29484,null],[29852,"2026-06-05T22:42:22",64,"//ммм, ещё вопрос, вы в каком темпе едете? Среднем?",29484,null],[29853,"2026-06-05T22:43:03",64,"//Кью первая, Жакио второй, Бхагар третий",29484,null],[29854,"2026-06-05T22:43:08",36,"//ну тип. Кью ещё по пути прислушивается к деревьям, слушая что они видели",29852,null],[29855,"2026-06-05T22:43:21",64,"//ебать, идеально",29853,null],[29856,"2026-06-05T22:43:31",64,"//окей окей",29854,null],[29857,"2026-06-05T22:43:34",5,"Минотавр едет не спеша. Ему очень хочется поболтать, но девочке Бхагар не доверяет, а тифлинг молчит как в воду опущенный",29484,null],[29859,"2026-06-05T22:43:47",64,"/roll 1d20",29484,null],[29861,"2026-06-05T22:43:52",64,"ЕБАТЬ",29484,null],[29862,"2026-06-05T22:43:55",36,"//пизда",29484,null],[29863,"2026-06-05T22:44:02",64,"😨😨😨",29484,null],[29864,"2026-06-05T22:44:05",36,"//деревья и трава что-то видели?",29856,null],[29865,"2026-06-05T22:44:44",64,"//щасссс",29864,null],[29867,"2026-06-05T22:45:25",64,"//ну там немного не то как хотел, а потому...",29860,null],[29872,"2026-06-05T22:51:37",36,"Пока я каталась то резко замедлилась и достала из за спины свой посох. Беру посох в руки\nДелаю движениями рук и теперь на моём посохе наконечник выглядит как серебрянный дракон.\n\n- Враги рядом...\n\nГоворю я товарищам прислушиваясь к шелесту листьев ожидая засады",29484,null],[29873,"2026-06-05T22:52:08",64,"//киньте внимательность все",29484,null],[29874,"2026-06-05T22:52:12",64,"//кроме черта",29484,null],[29875,"2026-06-05T22:52:13",5,"Минотавр внял предупреждению и достал алебарду.",29484,null],[29876,"2026-06-05T22:52:28",5,"/r +2",29484,null],[29878,"2026-06-05T22:52:32",64,"//угу",29484,null],[29879,"2026-06-05T22:53:16",64,"ты ничего не замечаешь, хотя знаешь что что то не так, не понимаешь что и где...",29876,null],[29880,"2026-06-05T22:55:32",64,"@Professor_3M653 внимательность",29484,null],[29881,"2026-06-05T22:55:41",36,"//ЩА ЩА",29880,null],[29885,"2026-06-05T22:57:51",36,"/r +5",29484,null],[29889,"2026-06-05T22:58:34",64,"О",29886,null],[29894,"2026-06-05T23:00:06",64,"какое то шевеление в кустах спереди и чуть дальше, вы едете вперед чуть медленнее... РАСТЯЖКА. Ты успеваешь её заметить потому остонавливаешь лошадь прям перед ловушкой... Остальные тоже остановилают лошадей прямо сзади тебя..",29484,null],[29896,"2026-06-05T23:00:19",64,"//Ну вы не наебнулись на 2д10 урона все ок",29484,null],[29897,"2026-06-05T23:00:40",5,"// может скинешь чуток...",29896,null],[29898,"2026-06-05T23:00:46",5,"// шучу",29484,null],[29899,"2026-06-05T23:01:14",64,"на дорогу выскакивает 4 гоблина, а сзади ворг... Инициатива ребятки, у них не вышло застать вас врасплох",29484,null],[29901,"2026-06-05T23:01:27",64,"/roll 1d20+2",29484,null],[29903,"2026-06-05T23:01:28",5,"вот и славно//",29484,null],[29904,"2026-06-05T23:01:32",64,"/roll 1d20+1",29484,null],[29906,"2026-06-05T23:01:34",5,"/r +1",29484,null],[29908,"2026-06-05T23:01:37",64,"Ебать",29484,null],[29909,"2026-06-05T23:01:55",5,"// кто за тифлинга?",29484,null],[29911,"2026-06-05T23:02:19",64,"//вы 4 гоблинов и волка без тифлинга не заточите?",29909,null],[29914,"2026-06-05T23:02:28",5,"// ладно",29484,null],[29915,"2026-06-05T23:02:46",5,"// ходить?",29484,null],[29917,"2026-06-05T23:02:51",36,"//я затащу",29911,null],[29918,"2026-06-05T23:03:29",36,"/r +2",29484,null],[29920,"2026-06-05T23:03:56",64,"1. Бхагар\n2. Кью\n3. Гоблины \n4. Ворг",29484,null],[29921,"2026-06-05T23:03:56",64,"Щас",29484,null],[29922,"2026-06-05T23:03:57",64,"Щас",29484,null],[29923,"2026-06-05T23:04:02",64,"Я зря чтоле карту делал",29484,null],[29924,"2026-06-05T23:04:39",36,"//тоже верна, не то что я ленивая жопа",29923,null],[29925,"2026-06-05T23:05:00",5,"Минотавр умело соскакивает с лошади и бежит на волка с алебардой на перевес. Укол прямо в пасть, затем обратная атака древком.",29484,null],[29926,"2026-06-05T23:05:14",5,"/r +6\n/r +6",29484,null],[29928,"2026-06-05T23:05:30",5,"/r d10+4\n/r d4+4",29484,null],[29932,"2026-06-05T23:05:57",5,"// 11 урона волку",29484,null],[29934,"2026-06-05T23:06:14",64,"//да обе",29927,null],[29935,"2026-06-05T23:06:24",64,"//что то ты как по пизде ладошкой",29932,null],[29936,"2026-06-05T23:06:38",36,"//а я на гоблинав)",29935,null],[29937,"2026-06-05T23:06:41",5,"// о прикольно",29931,null],[29939,"2026-06-05T23:06:55",64,"//щащаща",29484,null],[29940,"2026-06-05T23:07:00",64,"//сек гайс",29484,null],[29942,"2026-06-05T23:07:23",5,"// походу он жив",29484,null],[29943,"2026-06-05T23:07:31",64,"Ты меньше половины уебал",29942,null],[29944,"2026-06-05T23:07:43",36,"//я вас жду",29940,null],[29946,"2026-06-05T23:07:46",36,"//хулж",29484,null],[29947,"2026-06-05T23:07:50",5,"// тогда отхожу на шаг назад от ворга. Дистанция — 11 футов.",29484,null],[29948,"2026-06-05T23:07:50",5,"// конц хода",29484,null],[29949,"2026-06-05T23:07:56",64,"ворг чуть шатается от твоей атаки, но он жив и зол. Ход Кью",29484,null],[29951,"2026-06-05T23:08:06",64,"//сколько сколько?",29947,null],[29953,"2026-06-05T23:08:20",64,"//он по тебе провоцированно ударит?",29484,null],[29956,"2026-06-05T23:08:41",5,"//неа, у меня досягаемость",29484,null],[29958,"2026-06-05T23:08:57",5,"// алебарда длинная, зубы нет",29484,null],[29959,"2026-06-05T23:09:39",64,"//а древком бить тоже досягаемость?",29484,null],[29960,"2026-06-05T23:09:43",5,"// да",29484,null],[29961,"2026-06-05T23:09:47",64,"//понял",29484,null],[29963,"2026-06-05T23:10:09",64,"@Professor_3M653 ходи",29484,null],[29965,"2026-06-05T23:10:47",36,"Кью прытко спрыгивает с лошади подбегает к гоблину и замахнувшись палкой, которая засвятилась, хуярит по его голове\n\n- Получи грязный гоблин!",29931,null],[29967,"2026-06-05T23:10:57",36,"//точка это то куда я перешла",29965,null],[29968,"2026-06-05T23:11:10",64,"Спешиться это 1/2 твоей скорости есчо",29965,null],[29969,"2026-06-05T23:11:30",64,"Прям на лошади пиздуй хз",29484,null],[29970,"2026-06-05T23:11:45",9,"//Без тифлинга играете?",29484,null],[29971,"2026-06-05T23:11:47",5,"// там растяжка",29484,null],[29972,"2026-06-05T23:11:51",64,"//он спит",29970,null],[29973,"2026-06-05T23:11:59",5,"// обещал быть...",29970,null],[29974,"2026-06-05T23:12:02",64,"//так ее видно же, а ну или",29971,null],[29975,"2026-06-05T23:12:09",36,"//так у меня 30 футав",29968,null],[29976,"2026-06-05T23:12:16",5,"// а тогда перепрыгнуть можно",29974,null],[29977,"2026-06-05T23:12:19",64,"15 остаётся, это 3 гекса",29975,null],[29978,"2026-06-05T23:12:23",64,"//да",29976,null],[29979,"2026-06-05T23:12:50",36,"//та точку куда я встала это 5 гексов",29977,null],[29980,"2026-06-05T23:12:57",36,"//или о чём ты?",29484,null],[29981,"2026-06-05T23:13:02",36,"//слезть тип?",29484,null],[29982,"2026-06-05T23:13:05",36,"тогда верхом",29484,null],[29983,"2026-06-05T23:13:08",36,"//мне поху",29484,null],[29984,"2026-06-05T23:13:14",64,"//так бы сразу",29982,null],[29985,"2026-06-05T23:13:18",36,"//пусть лошадь пиздят\nвыше шанс выжить",29484,null],[29987,"2026-06-05T23:13:27",36,"/r +6",29484,null],[29989,"2026-06-05T23:13:32",64,"Попала",29484,null],[29990,"2026-06-05T23:13:58",36,"/r d8+d6",29484,null],[29992,"2026-06-05T23:14:15",36,"И пусть ещё два гоблина спас тела сделают",29991,null],[29993,"2026-06-05T23:14:43",64,"/roll 2d20",29992,null],[29995,"2026-06-05T23:14:49",64,"//один смог",29484,null],[29996,"2026-06-05T23:15:03",36,"//Ес на лошади то сюды",29963,null],[29997,"2026-06-05T23:15:19",36,"/r d6 Холодом тому кто не смог",29994,null],[29999,"2026-06-05T23:15:27",64,"//у меня гексы не поворачиваются",29996,null],[30000,"2026-06-05T23:15:29",64,"Ыыы",29484,null],[30001,"2026-06-05T23:15:30",64,"Лан",29484,null],[30002,"2026-06-05T23:15:37",64,"//он выжил чтооо",29998,null],[30006,"2026-06-05T23:17:08",64,"Тааакс",29484,null],[30008,"2026-06-05T23:17:45",36,"УРЯЯЯЯ\nМИНУС БОБЛИН",30006,null],[30014,"2026-06-05T23:19:25",64,"Ща щащкща",29484,null],[30015,"2026-06-05T23:19:45",36,"//мдя... тебе бы поучится быть быстрой",29484,null],[30017,"2026-06-05T23:20:30",64,"2 гоблина (что в кустах и что целый) стреляют в Кью, один рассыпает металлические шарики и убегает",29484,null],[30021,"2026-06-05T23:20:54",64,"/roll 2d20",29484,null],[30023,"2026-06-05T23:20:58",64,"Нихуя себе",29484,null],[30024,"2026-06-05T23:21:05",44,"// почему я на карте не вижу  тараска ?",30006,null],[30025,"2026-06-05T23:21:11",64,"/roll 2d6+2",29484,null],[30027,"2026-06-05T23:21:18",64,"@Professor_3M653 11 урона",29484,null],[30028,"2026-06-05T23:21:29",36,"//похую",30027,null],[30029,"2026-06-05T23:21:40",64,"//щас метеоритом добьем",30028,null],[30032,"2026-06-05T23:23:02",64,"Ворг подбегает и кусает тебя @elsio28",29484,null],[30033,"2026-06-05T23:23:09",64,"Есть там черта какая может?",29484,null],[30035,"2026-06-05T23:23:22",5,"Когда ворг подбегает, он напарывается на выставленную алебарду.",29484,null],[30036,"2026-06-05T23:23:25",5,"/r +6",29484,null],[30038,"2026-06-05T23:23:30",64,"Попал",29484,null],[30039,"2026-06-05T23:23:31",5,"/r d10+4",29484,null],[30041,"2026-06-05T23:23:36",64,"Уффф он жив",29484,null],[30042,"2026-06-05T23:23:40",36,"//ну обычного ддруида 2 уровня бы добила\nно у меня то +10 к хитам",30029,null],[30043,"2026-06-05T23:23:41",64,"/roll 1d20+5",29484,null],[30045,"2026-06-05T23:23:46",64,"Мимо я так понял",30044,null],[30046,"2026-06-05T23:23:58",64,"//откуда блкя🚬",30042,null],[30047,"2026-06-05T23:24:03",36,"//эта же шарики?",30020,null],[30048,"2026-06-05T23:24:07",64,"Да",30047,null],[30049,"2026-06-05T23:24:15",36,"//маг предмет от древа",30046,null],[30050,"2026-06-05T23:24:28",64,"//пиздец а мне",30049,null],[30051,"2026-06-05T23:24:52",5,"// меня укусить забыл? кд 14",30032,null],[30052,"2026-06-05T23:25:02",64,"Он промазал",30051,null],[30053,"2026-06-05T23:25:06",64,"Во",30044,null],[30056,"2026-06-05T23:25:23",64,"Твой ход, добивай",30051,null],[30057,"2026-06-05T23:25:55",5,"/r +6",29484,null],[30059,"2026-06-05T23:25:58",64,"//на половину дай бог пройдём сегодня",29484,null],[30060,"2026-06-05T23:26:01",64,"Мимо",30058,null],[30062,"2026-06-05T23:26:06",5,"/r +6",29484,null],[30064,"2026-06-05T23:26:10",64,"Попал",30063,null],[30065,"2026-06-05T23:26:13",5,"/r d4+4",29484,null],[30067,"2026-06-05T23:26:20",64,"Добил",30066,null],[30068,"2026-06-05T23:26:28",64,"А в любом случае как будто добил бы",29484,null],[30069,"2026-06-05T23:26:36",5,"Удар древком прямо по волосатой башке валит ворга на землю.",29484,null],[30071,"2026-06-05T23:27:09",64,"@Professor_3M653 твой ход",29484,null],[30072,"2026-06-05T23:27:24",5,"// погодь, я бегу к ближайшему гоблину",29484,null],[30073,"2026-06-05T23:27:33",5,"// останавливаюсь на дистанции 11 футов",29484,null],[30074,"2026-06-05T23:27:36",5,"// конец",29484,null],[30075,"2026-06-05T23:27:42",64,"Вот это деревья тут нельзя ходить",29484,null],[30076,"2026-06-05T23:27:49",64,"А окей",30072,null],[30079,"2026-06-05T23:28:52",5,"// @Professor_3M653",29484,null],[30080,"2026-06-05T23:29:08",36,"//у меня инет шакалит",30071,null],[30081,"2026-06-05T23:29:11",36,"//пргодите",29484,null],[30083,"2026-06-05T23:29:40",36,"Я же в курсе про долбаеба в кустах?",30075,null],[30084,"2026-06-05T23:29:49",64,"Ну его видно да",30083,null],[30086,"2026-06-05T23:30:26",36,"//а да пофиг, там этот... Сокомандник",30084,null],[30087,"2026-06-05T23:30:47",36,"Скока у лошади скорость?",30084,null],[30088,"2026-06-05T23:31:00",64,"60 нахуй",30087,null],[30092,"2026-06-05T23:31:42",64,"Да кинь уже фаербол",30086,null],[30098,"2026-06-05T23:37:32",36,"Кью верхом на лошади обходит шарики и на скаку пиздит боблина по башке, словно у неё клюшка а он шарик для гольфа",30078,null],[30099,"2026-06-05T23:37:38",36,"/r +6",29484,null],[30101,"2026-06-05T23:37:49",36,"/r d8+d6",29484,null],[30103,"2026-06-05T23:37:59",36,"//спас тела другому боблину",29484,null],[30104,"2026-06-05T23:38:09",64,"/roll 1d20",29484,null],[30106,"2026-06-05T23:38:12",64,"Убила",29484,null],[30107,"2026-06-05T23:38:14",64,"Всех",29484,null],[30108,"2026-06-05T23:38:16",64,"Нахуй",29484,null],[30109,"2026-06-05T23:38:18",64,"Ведьма",29484,null],[30110,"2026-06-05T23:39:19",36,"Когда дальний гоблин упал от ледяного дыхания головы дракона с конца посоха Кью радостно воскликнула\n\n- Ура!!! Трехочковый!!!",29484,null],[30111,"2026-06-05T23:39:33",36,"//а скока у второго боблина было?",30106,null],[30112,"2026-06-05T23:39:33",64,"//там 1 остался в кустах",29484,null],[30113,"2026-06-05T23:39:41",64,"//бля а",30111,null],[30114,"2026-06-05T23:39:47",64,"//я перепутал походу",29484,null],[30115,"2026-06-05T23:39:50",36,"//ну его добьёт другой",30112,null],[30116,"2026-06-05T23:39:50",64,"//по идеи 2",29484,null],[30117,"2026-06-05T23:39:57",36,"/r d6",30116,null],[30120,"2026-06-05T23:40:10",36,"Давай так",30119,null],[30121,"2026-06-05T23:40:12",64,"Чтоооо ваншот",29484,null],[30122,"2026-06-05T23:40:13",64,"Уфффф",29484,null],[30123,"2026-06-05T23:40:15",64,"Уффффф убила",29484,null],[30124,"2026-06-05T23:40:16",36,"Он все равно бы сдох",29484,null],[30125,"2026-06-05T23:40:33",5,"// тогда обратно по коням?",29484,null],[30126,"2026-06-05T23:40:59",64,"ластовый гоблин. Он использует отход и сбегает в лес крича что то по пути назад... Победа",29484,null],[30127,"2026-06-05T23:41:03",64,"//такс",29484,null],[30128,"2026-06-05T23:41:31",53,"//сетку в него!",30126,null],[30129,"2026-06-05T23:41:41",64,"@Professor_3M653 150 опыта за 3х гоблинов\n@elsio28 150 опыта за ворга и 1 гоблина",29484,null],[30130,"2026-06-05T23:41:57",64,"//там на ваше усмотрение но да",29484,null],[30131,"2026-06-05T23:42:09",64,"//можно долутать",29484,null],[30133,"2026-06-05T23:42:33",5,"// поч разный опыт за битву?",29484,null],[30134,"2026-06-05T23:43:05",64,"//потому что разное количество врагов побежденно, а ладно хуй с ним, последнего гоблина теж ебнули 150 тебе тоже",30133,null],[30135,"2026-06-05T23:43:06",64,"//все",29484,null],[30136,"2026-06-05T23:43:27",5,"*смотрю, что было у гоблинов и подбираю*",30131,null],[30137,"2026-06-05T23:43:33",64,"Щ",30136,null],[30138,"2026-06-05T23:43:36",36,"//мой лут пиздят!",30136,null],[30139,"2026-06-05T23:43:44",36,"//три боблина мои!",29484,null],[30140,"2026-06-05T23:43:51",5,"// тебе мясо",29484,null],[30141,"2026-06-05T23:43:51",36,"//Хсссс!!!",29484,null],[30142,"2026-06-05T23:44:14",64,"/roll 2d4*5",29484,null],[30144,"2026-06-05T23:44:20",64,"Ебать",29484,null],[30145,"2026-06-05T23:44:24",64,"40 зм",29484,null],[30146,"2026-06-05T23:44:42",64,"Нахуй вам эти скимитары испорченные и по 15 стрел",29484,null],[30147,"2026-06-05T23:44:57",5,"// тебе норм с бомжей гоблинов по 10 зм давать?",29484,null],[30148,"2026-06-05T23:45:00",5,"// ладно твоя игра",29484,null],[30149,"2026-06-05T23:45:22",64,"//ну, они с охоты пришли значит, богатый улов",30147,null],[30151,"2026-06-05T23:45:45",64,"// и там купец в кустах 😱",30149,null],[30152,"2026-06-05T23:45:51",5,"// ладно",30149,null],[30153,"2026-06-05T23:45:52",64,"//не этр шутка, там дальше",29484,null],[30154,"2026-06-05T23:46:06",64,"/roll 10d4/2",29484,null],[30156,"2026-06-05T23:46:09",64,"Что",29484,null],[30157,"2026-06-05T23:46:13",64,"/roll 10d4",29484,null],[30159,"2026-06-05T23:46:17",64,"Иди нахуй",30158,null],[30161,"2026-06-05T23:46:19",36,"Беру скимитары и 20 ЗМ \n\n- Сюдаааа\n\n//А к стрелам лука нету?",30146,null],[30162,"2026-06-05T23:46:31",5,"// ладно беру 20 зм и стрелы",29484,null],[30163,"2026-06-05T23:46:38",64,"11 стрел, 2 скимитара -1 и все",29484,null],[30164,"2026-06-05T23:46:49",36,"//Яс....",30163,null],[30165,"2026-06-05T23:46:52",36,"А деньги?",30163,null],[30166,"2026-06-05T23:46:58",64,"Вы забрали",30165,null],[30167,"2026-06-05T23:47:01",64,"40 зм",29484,null],[30168,"2026-06-05T23:47:14",64,"Я наверное вам за квест больше не дам денег а то чёт",30167,null],[30169,"2026-06-05T23:47:15",64,"Не",29484,null],[30170,"2026-06-05T23:47:15",5,"// едем дальше бож",29484,null],[30171,"2026-06-05T23:47:29",64,"//фух, щас",29484,null],[30172,"2026-06-05T23:47:33",64,"//минуточку гайс",29484,null],[30175,"2026-06-05T23:49:34",64,"//бля а дальше че",29484,null],[30176,"2026-06-05T23:49:38",64,"//а вот",29484,null],[30188,"2026-06-05T23:51:46",64,"Игроки ехали довольно долго, ещё пара часов в пути, ближе к ночи, когда почти стемнело они выехали к деревне, ещё меньшее поселение с рядом домиков и кажется трактиром, либо баром, в любом случае, в этом доме сейчас пили и громко кричали. Время уже позднее, вам нужно найти старейшину местного. Герои, что вы делаете?",29484,null],[30191,"2026-06-05T23:52:42",5,"— Трактир? Мы заслужили отдых.\n\nПодъезжаю ко входу и врываюсь в трактир.",29484,null],[30192,"2026-06-05T23:53:00",64,"//похуй, бес на лошадях",30191,null],[30193,"2026-06-05T23:53:02",36,"Кью зевает и потягивается \n\n- Ах~ Как сладок хруст костей существ из плоти... ОЙ!...\n\nПосмотрела на минотавра\n\n- Я к старосте",30188,null],[30194,"2026-06-05T23:53:05",5,"— Бочонок медовухи усталому минотавру!",29484,null],[30195,"2026-06-05T23:53:21",64,"//щащаща",30194,null],[30196,"2026-06-05T23:55:29",64,"ты проходишь в трактир, либо что это? Небольшой домик, внутри - барная стойка где стоит крепко сложеный мужчина и раздаёт напитки. Да, кажется, тут только пьют, это бар, но отдохнуть можно. Свободен 1 столик, за остальными двумя группы каких то людей что то громко обсуждают между собой... Мужчина, судя по всему бармен, говорит грубым низким голосом:\n—а ты кто?",30194,null],[30197,"2026-06-05T23:56:12",5,"— Бхагар, дорогие друзья! Постоянный посетитель мест с отличной выпивкой!",29484,null],[30199,"2026-06-05T23:57:14",36,"Кью же несмотря на заманчивое предложение минотавра пошла в сторону домика старосты, что явно можно было легко найти. Для лучшего ориентирования она использовала свечку",30193,null],[30200,"2026-06-05T23:57:17",64,"он удивленно смотрит на тебя \n—впервые слышу? И откуда ты?\nон отворачивается и наливает кружку какого то пойла\n—2 серебра",30197,null],[30201,"2026-06-05T23:57:27",64,"//а хули оно стонет",30193,null],[30202,"2026-06-05T23:58:39",64,"ох, но все дома, кроме бара, почти не отличаются... Кинь анализ",30199,null],[30204,"2026-06-05T23:59:18",36,"Анализ",30202,null],[30205,"2026-06-05T23:59:20",36,"А... Ок",29484,null],[30206,"2026-06-05T23:59:24",5,"— Слышал про легион Бороса? Я прибыл из диких степей в поисках лучшей выпивки. Спасибо, хозяин!",30200,null],[30207,"2026-06-05T23:59:30",5,"*кладу 2 серебряных*",29484,null],[30208,"2026-06-06T00:00:11",64,"—приводи своих Боросов сюда, всех напоим!\nв баре продолжаются действия что были до... Ты отдыхаешь",30206,null],[30209,"2026-06-06T00:00:45",36,"/r",29484,null],[30211,"2026-06-06T00:00:58",64,"Пойдёт",30210,null],[30212,"2026-06-06T00:01:44",64,"ну, не сложно догадаться прочесть таблички перед домом. Дом старосты был такой же как остальные, он перед тобой. Что ты делаешь?",29484,null],[30214,"2026-06-06T00:02:05",5,"Минотавр радостно пьёт всю ночь напролёт.",30208,null],[30215,"2026-06-06T00:02:11",36,"Стучусь в дверь\n\n Своими маленькими кулочками",30212,null],[30216,"2026-06-06T00:02:36",64,"//тебя щас спать погонят по рельсам моим постой брат",30214,null],[30217,"2026-06-06T00:02:46",64,"//а лан похуй, пусть в баре спит",29484,null],[30221,"2026-06-06T00:05:58",64,"ты едва слышно стучишься в дверь, этот стук, хоть и тихий, но прерывает почти полную тишину вокруг... И шум бара. В скоре ты слышишь шаги, медленные но приближающиеся. Дверь открывается, на пороге стоит пожилой мужчина со свечкой в руках, он окутан в зверинные шкуры черного цвета. Мужчина видит тебя и говорит:\n—ты чьё, исчадье?",30215,null],[30223,"2026-06-06T00:07:06",36,"- Я не исчадье!\n\nНадулась и топнула своей ножкой Кью мило всхлипывая",30221,null],[30225,"2026-06-06T00:08:19",64,"Старец почесал свою бороду явно задумываясь о чем то, а после сказал:\n—ну, здравствуй, Неисчадие, я - Ковур, старейшина этой деревни, зачем вы тут?",30223,null],[30228,"2026-06-06T00:12:27",36,"- Правда?\n\nОна посмотрела на тебя жалобными глазками, затем выпрямилась, быстро вытерла слезы и гордо изредка всхлипывая сказала\n\n- Я Кью! *Всхлип* Мы пришли в поисках купца другой деревни *всхлип*",30225,null],[30229,"2026-06-06T00:15:01",64,"Ковур переменился в лице \n—ох, так вы за купцом? Чтож ты сразу не сказала? Ты не одна? Мы так обыскались его, право, если найдёте будем благодарны. Мы всей деревней его ждём, а его все нет и нет, у нас экономика встала, куда это идёт?",30228,null],[30230,"2026-06-06T00:18:10",64,"@Jak_Zak братанчек вставай",29484,null],[30231,"2026-06-06T00:18:26",5,"// давайте пытайте старосту",29484,null],[30232,"2026-06-06T00:18:30",5,"// я бухаю",29484,null],[30233,"2026-06-06T00:18:44",64,"//топ 1 дамагер пачки развлекается",30232,null],[30234,"2026-06-06T00:18:55",36,"//э?",30233,null],[30235,"2026-06-06T00:19:15",64,"//а он стабильнее",30234,null],[30236,"2026-06-06T00:19:23",64,"🤫🤫🤫",29484,null],[30237,"2026-06-06T00:19:29",36,"- Значит и вы ничего не знаете.... *Всхлип* Расскажете, что вы видели в последний раз?",30229,null],[30238,"2026-06-06T00:20:53",64,"—да я не видел его.. я бы рассказал больше, но так спать хочу, может, утром? Вы на лошадях или пешим сюда шли?",30237,null],[30239,"2026-06-06T00:25:30",36,"- На лошадях, у вас есть конюшня?",30238,null],[30240,"2026-06-06T00:26:24",64,"—есть, если хотите можете в баре переждать и у бармена же спросить про конюшню, у него вроде комнаты в подвале были, если я не запамятовал",30239,null],[30241,"2026-06-06T00:26:44",64,"// @elsio28 хочешь к тебе орки доебутся? Я тоже нет",29484,null],[30242,"2026-06-06T00:27:24",5,"// а что им надо? Пускай пьют",30241,null],[30243,"2026-06-06T00:27:33",5,"// я вообще спать пойду",29484,null],[30244,"2026-06-06T00:27:46",5,"// вы доигрывайте день пока синька бухает",29484,null],[30245,"2026-06-06T00:27:54",64,"//когда что куда",30243,null],[30246,"2026-06-06T00:28:00",5,"// ирл",29484,null],[30247,"2026-06-06T00:28:08",36,"- А у вас мона?",30240,null],[30248,"2026-06-06T00:28:11",64,"//спокойной ночи брат",30246,null],[30249,"2026-06-06T00:28:15",64,"Лиза",30247,null],[30251,"2026-06-06T00:28:49",64,"//дети сами на зуб минотавру лезут, что за время пошло",30247,null],[30252,"2026-06-06T00:29:11",64,"//поспать типо?",30247,null],[30253,"2026-06-06T00:29:19",36,"//да",30252,null],[30254,"2026-06-06T00:30:42",64,"—ну... У меня есть комната для гостей, если хочешь иди...\nну и старик стоит чето ждёт",30247,null],[30255,"2026-06-06T00:31:08",64,"//щас мы тоби за лича отомстим",29484,null],[30256,"2026-06-06T00:31:45",36,"- Щас тогда коней отведу!\n\nВесела ответила Кью и убежала отводить коней в бар, попросила отвезти двоих товарищей спать, оплатила им комнаты и аренду конюшен. Затем вернулась и легла спат",30254,null],[30257,"2026-06-06T00:32:49",64,"//ну там 2 зм суммарно потратили",30256,null],[30258,"2026-06-06T00:33:01",36,"Поху \nУ меня 120",30257,null],[30259,"2026-06-06T00:33:09",64,"//все, все по комнатам, описывать гостевую чи в пизду?",29484,null],[30260,"2026-06-06T00:33:22",64,"//даааа, жалко наверное будет если кто то вырубит и заберёт их",30258,null],[30261,"2026-06-06T00:33:58",36,"Все это у нее внутри тела, у неё нет ни сумки, ни рюкзака",30260,null],[30262,"2026-06-06T00:34:05",36,"//дап",30259,null],[30263,"2026-06-06T00:34:16",64,"//это будет самое мерзкое ограбление в ее жизни",30261,null],[30264,"2026-06-06T00:35:56",36,"//ты же понимаешь что я в таком случае тоже проснусь?",30263,null],[30267,"2026-06-06T00:36:29",64,"комната не самая большая, примерно 20 на 20 футов, небольшая пастель, шкаф для вещей, окно, стол и стул. На полу постелен ковёр с странными узорами, а на стене странная картина, где какой то воитель обращается в неведомую абберацию в зелёном свечении... Дверь можно на щеколду запереть изнутри",30262,null],[30268,"2026-06-06T00:36:44",64,"//ну не у старика же грабить",30264,null],[30269,"2026-06-06T00:37:04",64,"//ему эта помощь нужнее всего он головой за деревню отвечает",30268,null],[30270,"2026-06-06T00:37:06",36,"//я и не планировала у него грабить",30268,null],[30271,"2026-06-06T00:37:26",64,"//✅✅",30270,null],[30272,"2026-06-06T00:37:54",64,"//ну все чота рассосались, щас инфу дам и наверное все на сегодня",29484,null],[30273,"2026-06-06T00:38:21",36,"Угум",30272,null],[30274,"2026-06-06T00:38:23",36,"Баиньки",29484,null],[30282,"2026-06-06T00:44:13",64,"ну ты просыпаешься, старик выпроваживает тебя и у выхода говорит\n—не знаю я, где Малсер-купец, но знаю я где он ещё остонавливался. Малсер по деревням ездит и торгует, покупает, продаёт, с города. Есть в этом маршруте ещё одна деревня, деревня Брандар. Там он остонавливается обычно перед выходом и к нам едет, пади там где задержался? В общем, езжайте туда, вам нужно пройти к западу деревни, там большая дорога и развилка с указателями, держитесь правее всегда, никогда не съезжайте влево, там лес темный, бог его знает что там живёт, там даже тропы нету. Держитесь луга в дороге, а не леса. Надеюсь вы найдёте Малсера где нибудь в Брандаре, передай всем удачи от меня, Кью!",29484,null],[30283,"2026-06-06T00:44:23",64,"//бэ",29484,null],[30284,"2026-06-06T00:44:36",64,"//хороший кусок маневров на импровизации",29484,null],[30285,"2026-06-06T00:47:08",64,"//чето вы как ножом по маслу раскаленным идёте, надо вам сложнее сделать а то наград много чёт",29484,null],[30288,"2026-06-06T00:47:42",64,"//и щас я понял что никому в рот того не еблась моя главная награда",30285,null],[30292,"2026-06-06T00:49:56",64,"//такс, ДК, подожди, то есть у тебя теперь информация как продолжать по рп и тебя не будет до четверга?",30274,null],[30296,"2026-06-06T00:51:51",36,"//ага",30292,null],[30306,"2026-06-06T00:54:55",64,"//чет как то проклято проходят сборы на кампейны когда ты в пачке  🌸",30296,null],[30578,"2026-06-06T09:40:37",42,"// да, конечно. Извиняюсь что не получилось. Летящая взрывака упала на вышку связи",29538,null],[30579,"2026-06-06T09:41:05",42,"// щас уже починили еë и всë гуд",29484,null],[30580,"2026-06-06T09:52:36",64,"//это конечно круто но у нас как будто до четверга не, хз",30578,null],[30583,"2026-06-06T10:52:45",5,"// до четверга как-то долго",29484,null],[30584,"2026-06-06T10:53:00",5,"// как насчёт продолжать проходить пока 2 игрока онлайн есть",29484,null],[30597,"2026-06-06T11:47:58",42,"//В понедельник я вожу игру",29554,null],[30602,"2026-06-06T11:49:54",36,"сегодня если и смогу, то размыто",30597,null],[30608,"2026-06-06T12:25:52",64,"//хз хз, там делов то осталось на пару часов игры и в худшем случае 3 боевки, в лучшем 1, ну вообще ещё чуть можно пройти, там между собой договоритесь если все не против то делаем",30584,null],[30617,"2026-06-06T13:35:17",5,"Утром минотавр обнаружил себя лежащим на столу трактира. Он поднялся, потянулся, а затем решительно встал и вышел вон.\n\nНа улице Бхагар отправился искать своих спутников.",29484,null],[30618,"2026-06-06T13:37:12",36,"//не, тебя сонным в комнаты увели",30617,null],[30619,"2026-06-06T13:37:17",36,"//которые оплатила кью",29484,null],[30621,"2026-06-06T13:43:07",5,"// ерунда. Никто не вытащит миньку из трактира",30618,null],[30622,"2026-06-06T13:46:02",42,"// такс надо продумать как себя впихнуть",29484,null],[30623,"2026-06-06T13:46:06",5,"// может в формате постепенных постов играть будем? Пишем как свободны пост, а дм ведёт",29484,null],[30624,"2026-06-06T13:46:18",5,"// тебя привезли с собой на лошади",30622,null],[30625,"2026-06-06T13:46:38",42,"// ну тогда огэй",30624,null],[30626,"2026-06-06T13:46:40",36,"//и вот он точно спыт в комнате",30624,null],[30627,"2026-06-06T13:46:48",36,"можна",30623,null],[30628,"2026-06-06T13:47:32",42,"// это да, кровавые занятия дело утомительное",30626,null],[30629,"2026-06-06T13:49:04",5,"// кровавое наблюдение как другие режут гоблинов",30628,null],[30630,"2026-06-06T13:56:05",64,"//та пусть",30618,null],[30631,"2026-06-06T13:57:12",64,"//ты там в трактире в подвале в комнате ночевал",30622,null],[30632,"2026-06-06T13:58:57",42,"//оки",29484,null],[30633,"2026-06-06T13:59:16",36,"//напиши что видит кью\nпо возможности буду писать посты",30608,null],[30634,"2026-06-06T14:02:38",64,"//бля, ну... Если хотите то можно да",30623,null],[30635,"2026-06-06T14:02:56",64,"//как освобожусь мб",30633,null],[30638,"2026-06-06T14:12:30",5,"— Так, первый делом надо найти лошадей.\n\nНемного осмотревшись, минотавр увидел знакомых лошадей в конюшне у трактира. Он вывел и оседлал их. Затем прислонился к дереву неподалёку и стал ждать спутников.",29484,null],[30709,"2026-06-06T17:55:17",64,"Герои просыпаются, Жакио выходит из подвальной комнаты и идёт к своим союзниками, Бхагар уже стоит с лошадьми у выезда с деревни и терпеливо ждёт остальных, а Кью выходит из дома старца с полученной информацией, она пересекается с Жакио и они вместе идут дальше видя вдалеке Бхагара с лошадьми... Раннее тро в деревне, спят только лодыри, большая часть деревни пашет в поле, несколько мужиков чинят чей то дом, сопровождают работу легкое пение птиц и свежий запах, прошедшего ночью лёгкого дождя. Что вы делаете? \n@elsio28 @Professor_3M653 @Jak_Zak\n😨😨😨😨😨😨",29484,null],[30714,"2026-06-06T17:59:30",36,"//ничего не делаю, максимум говорю другим куда нам нада, понимаю что те не понимают и веду их туда куда нада, по пути так же общаясь с деревьями иногда напивая \"Ярарара\"",30709,null],[30732,"2026-06-06T18:32:01",64,"//это в \"**\" надо как будто",30714,null],[30733,"2026-06-06T18:35:21",42,"°выйдя из комнаты Жакио потянулся и громко зевнул°\nАаааггхх.. Вот бы выпить чорячего кофе.. \n°выглядит после пробуждения всë равно уставшим и почесал зад°",30709,null],[30734,"2026-06-06T18:41:26",64,"//лучший отыгрыш",30733,null],[30735,"2026-06-06T18:41:30",64,"//лан щас вас отправлю",29484,null],[30736,"2026-06-06T18:42:01",64,"//ну позже чуть, как дела рассосутся",29484,null],[30744,"2026-06-06T18:54:45",5,"— А вот и вы! Отправляемся? Куда нам дальше ехать?\n\nМинотавр залезает на лошадь и готовится следовать за остальными в конце строя",29484,null],[30748,"2026-06-06T18:56:19",36,"Кью рассказывает то что ей поведал старик старейшина",30744,null],[30767,"2026-06-06T19:12:04",42,"°Жакио садится на лошадь и ведëт впереди строя, продолжая потихоньку дремать не засыпая°",29484,null],[30768,"2026-06-06T19:14:38",36,"//впереди я, ты замыкающий",30767,null],[30769,"2026-06-06T19:14:43",64,"//океееееееееееей, значит ты ведёшь и я броски от тебя буду бросать 😊",30767,null],[30770,"2026-06-06T19:14:52",36,"//ибо нехуй тебе идти туда куда ты даже не знаешь...",29484,null],[30771,"2026-06-06T19:14:54",42,"// о как",29484,null],[30772,"2026-06-06T19:14:57",36,"//м.....",30769,null],[30773,"2026-06-06T19:15:12",64,"//между собой определите там по рп может",29484,null],[30774,"2026-06-06T19:15:14",42,"// ну не, я просто в центре тогда, если спереди дк",29484,null],[30775,"2026-06-06T19:15:18",64,"//ну я пока не пишу",29484,null],[30776,"2026-06-06T19:15:42",42,"// в конце минотоша",29484,null],[30777,"2026-06-06T19:16:07",36,"//ну вот ты внимательный? Знаешь куда идти? У тебя многа хитов?",30774,null],[30778,"2026-06-06T19:17:27",42,"// да, возможно, да многа",30777,null],[30779,"2026-06-06T19:17:47",36,"//скока? У Кью 30-32",30778,null],[30780,"2026-06-06T19:19:04",42,"// ладно, для перса первого уровня много 15",29484,null],[30781,"2026-06-06T19:20:27",42,"// лады, я в центре",29484,null],[30782,"2026-06-06T19:21:30",64,"и так... Герои садятся на лошадей и выдвигаются к Брандару. Путь может лежать через лес либо поле, право выбора за игроками, точнее, за ведущим отряда... Куда герои едут? По лесу? (левее) либо по лугу? (правее). Пока герои не выехали из деревни у них есть время поменять очередь и выбрать лидера. Что вы делаете?",29484,null],[30783,"2026-06-06T19:25:32",42,"°Жакио выглядывает и всматриватся на местность°\nМда.. Лишь трава и деревья.. О!\n°улавливает на взгляд Кью и говорит ей°\nОпа, ты же вреде из травы и растений. Наверное тебе знать куда лучше",29484,null],[30784,"2026-06-06T19:25:59",36,"\"В лес нельзя, едем по лугу\". Думает Кью так как помнит слова старейшины",30782,null],[30785,"2026-06-06T19:28:17",5,"// все здесь? ничего себе",29484,null],[30786,"2026-06-06T19:29:10",42,"//да",29484,null],[30787,"2026-06-06T19:29:38",5,"— По лугу, по лугу едем. Нечего в лес соваться, там мертвяки вылезут того и гляди. Если купец там, то уже мёртвый",30782,null],[30789,"2026-06-06T19:30:38",5,"Минотавр высказывает мнение, но держится позади всех. Он не хочет заплутать один.",29484,null],[30790,"2026-06-06T19:30:40",42,"- а за тело нам не заплатятят?",29484,null],[30791,"2026-06-06T19:32:39",5,"— Может и заплатят. Но как мы будем искать тело в лесу? Сказали ехать в деревню, там и узнаем, был ли у них купец вообще",29484,null],[30793,"2026-06-06T19:33:45",42,"- и то верно, лес оставим на последок, вооооот на саммыыый последок",30791,null],[30794,"2026-06-06T19:34:13",5,"// едем в поле дм",29484,null],[30795,"2026-06-06T19:34:21",42,"//йяп",29484,null],[30798,"2026-06-06T19:34:43",64,"//🎉🎶🙅‍♂️😧🥰😧😳😳😳🥰👩‍❤️‍👩😭😭😴😭😶‍🌫️💃🩲🐖🐖🍗🪨🪨🤰🌱😑🙁😐🤪🥰🐱💦",29484,null],[30799,"2026-06-06T19:34:48",64,"//окей",30794,null],[30801,"2026-06-06T19:35:03",64,"//щас вам минут через 5 отпишу",29484,null],[30802,"2026-06-06T19:35:40",42,"// пока ролевой момент и важная штука в отыгрыше кровавого охотника",29484,null],[30804,"2026-06-06T19:36:09",64,"//чешет задницу",30802,null],[30807,"2026-06-06T19:37:52",42,"°по пути жакио взял лезвие из Кормана и порезал ладонь и кровь выходила не каплями как у других а резким и выстрым водопадом шепча что-то на инфернальном°",29484,null],[30814,"2026-06-06T19:41:49",64,"//це шо",30807,null],[30815,"2026-06-06T19:41:55",64,"//кармана*",30807,null],[30816,"2026-06-06T19:48:02",42,"/r 1d4",29484,null],[30817,"2026-06-06T19:48:35",42,"/ладно",29484,null],[30820,"2026-06-06T19:49:22",42,"// кубики меня игнорируют",29484,null],[30821,"2026-06-06T19:49:41",42,"/roll 1d4",29484,null],[30824,"2026-06-06T19:49:59",42,"/ ООО!! Каеф",29484,null],[30826,"2026-06-06T19:50:38",42,"// подготовка к усиленной версии кровавого заговора",30814,null],[30829,"2026-06-06T19:54:57",5,"// где засада?",29484,null],[30832,"2026-06-06T19:57:23",42,"// не, это работает по другому, типо делаю ритуал и трачу хп в моëм случае 3 и следующее зачаровывание крови усилено и +3 сложности сп",30829,null],[30833,"2026-06-06T19:58:21",42,"// но увы у меня нету заговоров на спасы, только гарант за реакцию",30832,null],[30843,"2026-06-06T20:19:31",64,"//это на что",30822,null],[30844,"2026-06-06T20:19:54",64,"//понял",30832,null],[30845,"2026-06-06T20:20:05",5,"// где продолжение?",30844,null],[30846,"2026-06-06T20:20:05",64,"//хбебы ебучие",29484,null],[30847,"2026-06-06T20:20:19",64,"//скоро будет ребятки",30845,null],[30848,"2026-06-06T20:20:38",42,"// сорянчик, в следующие разы могу монаха сделать",30846,null],[30849,"2026-06-06T20:20:56",64,"//та все норм, я рофлю",30848,null],[30850,"2026-06-06T20:21:15",42,"// старался брать самую известную и понятную для игроков и мастера",29484,null],[30851,"2026-06-06T20:21:24",42,"// оГЕЙ",30849,null],[30852,"2026-06-06T20:28:23",64,"Вы едете дальше по лугу, путь довольно долгий, не смотря на то что вы скачете с хорошей скоростью. Слева, очень далеко, лес; такой маленький, от сюда как на ладони, между вами луг, справа почти тот же луг, пара табличек с названиями странных деревень и деревни \"Брандар\" прямо. Ехать ещё долго, выехав утром(к ≈6:00), вам предстоит ехать до раннего вечера (к 16:30~17:00). Быть может вы хотите ускорить темп? Или развлечь себя в дороге?",29484,null],[30853,"2026-06-06T20:28:27",64,"//хзхз",29484,null],[30854,"2026-06-06T20:29:58",36,"Ускоримся, но я все равно буду вглядываться в мелочь и прислушиваться к словам растений (они иногда говорят мне сами о опасности)",30852,null],[30855,"2026-06-06T20:30:50",64,"//ну, иногда так иногда",30854,null],[30856,"2026-06-06T20:31:01",42,"Лучше пострадаем сейчас, чем потом и подольше",30852,null],[30857,"2026-06-06T20:31:26",64,"//щас скажу скок тогда ехать",29484,null],[30859,"2026-06-06T20:40:02",5,"— Как по мне, спешить некуда. Но положусь на вас, глядите в оба!\n\nБхагар достал из рюкзака кусок жареного и с жадностью принялся его есть.",30854,null],[30860,"2026-06-06T20:40:20",5,"// ок едем быстро",29484,null],[30874,"2026-06-06T21:08:14",64,"//сорян дела были, щас доделаю",30857,null],[30890,"2026-06-06T21:32:32",64,"@Professor_3M653 ты ж щас ведёшь всех?",29484,null],[30891,"2026-06-06T21:32:51",36,"//ага",30890,null],[30895,"2026-06-06T21:35:28",64,"ты смотришь не заостряя внимательность на детали, тебе кажется что все нормально (пассивная внимательность 10(15-5)). Осмотришься?",30854,null],[30897,"2026-06-06T21:37:33",36,"Так как я ко всем скептически отношусь, особенно после недавней засады то да, осматриваюсь",30895,null],[30898,"2026-06-06T21:38:12",36,"/r +5",29484,null],[30901,"2026-06-06T21:38:40",5,"// го драться",29484,null],[30902,"2026-06-06T21:39:10",36,"//между собой? Ебанько?",30901,null],[30903,"2026-06-06T21:40:11",64,"//деритесь",30901,null],[30904,"2026-06-06T21:40:22",5,"// ну пиши нам ивент",29484,null],[30906,"2026-06-06T21:41:34",36,"//он сражение хочет",30903,null],[30907,"2026-06-06T21:41:37",64,"твой результат даёт тебе уверенность в том что все нормально, кажется, ничего необычного. Да и где ему быть, все вокруг как на ладони только если невидимый кто...",30899,null],[30908,"2026-06-06T21:41:38",36,"//что я вижу?",30899,null],[30909,"2026-06-06T21:41:55",64,"//это потом",30904,null],[30910,"2026-06-06T21:42:24",64,"//поставьте его в лидера я вам максимум битв накину, 4/4 а не 2/4 как возможно",30904,null],[30911,"2026-06-06T21:42:36",5,"// ладно не",30910,null],[30912,"2026-06-06T21:42:44",5,"// ну раз ничего нет, то едем в деревню",29484,null],[30913,"2026-06-06T21:42:48",64,"//да давай че ты, весело ж будет",30911,null],[30914,"2026-06-06T21:44:01",64,"с учётом более быстрой скорости, обернетесь чуть позже чем к полудню (к часу дня где то)",29484,null],[30915,"2026-06-06T21:44:32",64,"//я наверное ещё чуть позже опишу деревню и куда вам",29484,null],[30916,"2026-06-06T21:45:26",5,"// ещё позже(",30915,null],[30921,"2026-06-06T21:48:55",64,"//обязательства пунктуальности сняли 👹\n//но вы в любом случае завтра ещё играть сможете?",30916,null],[30926,"2026-06-06T21:51:56",5,"// зря сняли. Смогу, я хочу доиграть этот квест..",29484,null],[30935,"2026-06-06T21:59:28",64,"// мой квест хотят 🤩🤩🤩🤩",30926,null],[31120,"2026-06-06T22:49:22",64,"Вот и он, Брантар. Великая деревня, больше тех которые вы видели. Вы торжественно, по крайней мере для себя, въезжаете туда. Тут народу по более будет, прям небольшой город с кучей домиков. Видна лавка торговца, где он обычно стоит и живущую своей жизнью просторную деревню, с едва живыми улицами. Герои, что вы делаете? \n@Professor_3M653 @elsio28 @Jak_Zak",29484,null],[31201,"2026-06-06T22:59:22",5,"— Нам ведь к старосте надо? Хм, может торговец тоже знает о купце, они наверняка приятели.\n\n*Иду к лавке торговца*",29484,null],[31262,"2026-06-06T23:09:31",64,"//ыыы блять я еблан формулировки. Лавка для торга, там теж стоит купец этот самый или любой другой барыга и продаёт что нибудь. Типо мини рынок в 1 кабинку",31201,null],[31263,"2026-06-06T23:09:34",64,"//сорян",29484,null],[31266,"2026-06-06T23:10:02",5,"*подхожу к лавке и спрашиваю, был ли в городе купец*",29484,null],[31268,"2026-06-06T23:10:09",5,"// любой барыга в деревне должен знать",29484,null],[31271,"2026-06-06T23:10:26",64,"//окей щассс",31266,null],[31415,"2026-06-07T00:18:15",64,"ты подходишь к Лавке там вроде никого нет... Но случайный похожий. Ты подходишь и спрашиваешь у него - невысокий молодой паренёк, лет 17ти в простой одежде говорит тебе:\n—вы про Малсера? Он чуть больше недели назад заезжал сюда, поторговал тут, да пошёл в трактир передохнуть. Я видел как он утром, через день, собирал вещи у трактира в торопях. Может трактирщик знает больше?\nпарень указывает в сторону крупной хижины с вывеской \"Не тихий омут\" и идёт дальше по улице...",31266,null],[31823,"2026-06-07T13:20:51",5,"- Да, про него. Что ж, и купить тут ничего не получится. Спасибо, парень.\n\nМинотавр отправляется в трактир.\n\n- Интересное название. Клянусь рогами, гулянки тут веселые. Но ладно, рано ещё для этого",29484,null],[31837,"2026-06-07T13:31:55",5,"Бхагар находит трактирщика и расспрашивает об обстоятельствах отбытия Малсера",29484,null],[31854,"2026-06-07T13:37:10",64,"Бхагар входит в трактир, крупное здание с двумя этажами, на первом можно выпить и поесть. Куча столиков за которыми сидят случайные работяги. Стойка за, которой стоит невысокий, крепко сложеный мужчина с рыжей растительностью на лице. Он говорит: \n—Бронн приветствует вас в \"Не Тихом Омуте\", желаете выпить? \nЧто конкретно Бхагар говорит трактирщику?",31837,null],[31863,"2026-06-07T13:38:39",5,"-Здорово, Бронн! А меня зову Бхагар. Налей-ка мне кружечку чего хорошего. Только немного, рано всё-таки.",31854,null],[31870,"2026-06-07T13:40:37",5,"Минотавр остается у стойки и немного отпив, спрашивает трактирщика.\n\n- Слышал я, неделю с тому останавливался у вас купец Малсер. А до следующей деревни не добрался. Не подскажешь ли, при каких обстоятельствах он выехал от вас. Может говорил чего?",29484,null],[31871,"2026-06-07T13:40:52",64,"—слово клиента - закон!\nкакое то пойло быстро оказывается у тебя в кружке и подкатывает к тебе ;]\n—3 медняка",31863,null],[31873,"2026-06-07T13:41:31",5,"*плачу*",31871,null],[31911,"2026-06-07T13:52:46",64,"—Ох черт, не приехал дальше Малсер? Я ж говорил ему! Какой он безответственный. Был он тут, аккурат неделю назад, хотел отдохнуть после торгов, да понесло его на спиртное. Весь день в трактире пробухал, на ночь тут остался, а на утро проснулся и под ругань стал собирать вещи. Я его предупредил: \"ты, если опаздываешь, лучше просто темпу прибавь через луг. Через лес не едь, там недавно семья целая пропала с мужиком охотником. Явно не звери людей воруют\", он в ответ что то недовольно пробурчал \"мне некогда, я из графика и так выхожу сильно\". В общем, походу в лес поехал\nБронн отходит и протирает кружку\n—если не вернулся то либо умер, либо потерялся в лесу. Там, на дороге сюда из Скреба в лес можно было свернуть, вот он так и поехал, дороге короче то",31870,null],[31916,"2026-06-07T13:54:03",5,"- Ох, значит всё-таки в лес. Мы отправимся его искать. Не подскажешь что полезное про лес этот? Что за напасть там бродит?",29484,null],[31926,"2026-06-07T13:56:41",64,"—да черт ее знает, пару раз живые от туда приходили, да обезумевшие уже. Маги, друиды ходят, проверяют лес, говорят лес как лес, обычный, просто очень темный. В общем не знаю, если туда пойдёте, то только удачи могу пожелать\nБронн продолжает свою деятельность в трактире, вскоре к нему подходит клиент и у них затягивается беседа. Кажется он будет занят ещё некоторое время...",31916,null],[31931,"2026-06-07T13:57:35",5,"-  Ладно, здесь больше ничего не узнать. Надо действовать",29484,null],[31935,"2026-06-07T13:57:57",5,"Минотавр возвращается к спутникам и рассказывает все, что узнал",29484,null],[31936,"2026-06-07T13:58:18",5,"Теперь он знает, куда двигаться, поэтому занимает место впереди колонны",29484,null],[31942,"2026-06-07T13:59:00",5,"Отряд поворачивает на ту же самую дорогу и едет по ней, ища место, где купец свернул в лес.",29484,null],[31952,"2026-06-07T14:02:38",64,"съезд в лес почти у самой деревни, слева луг, справа лес. Просто вы едете в обратную сторону. Вы въезжаете в темный и дремучий лес...",31942,null],[31962,"2026-06-07T14:05:58",5,"- Здесь опасно. Едем осторожно, смотрим по сторонам, не шумим.\n\nЕдем по лесу, максимально бдительные.",29484,null],[31980,"2026-06-07T14:10:27",64,"//дилемма, если ехать медленно вы тут до ночи просидите, а хуй его знает кто тут ночью быть может, а если в среднем темпе вас внезапно могут по темечку отрубить",31962,null],[31981,"2026-06-07T14:10:40",64,"// кинь на выживание пока что",31962,null],[32015,"2026-06-07T14:17:16",5,"/r +2",29484,null],[32025,"2026-06-07T14:19:00",5,"// окей, первый час едем максимально осторожно, потом в среднем темпе",29484,null],[32035,"2026-06-07T14:19:43",64,"//такс",32016,null],[32047,"2026-06-07T14:21:49",64,"ты ведёшь пачку по лесу, кажется, что все нормально... Но в глубине души ты понимаешь что кажется вы потерялись... Едете осторожно, но не понимаешь куда именно",32025,null],[32048,"2026-06-07T14:21:58",64,"//щас я там закончу и кину вам кое кого",29484,null],[32061,"2026-06-07T14:23:38",5,"// давай",29484,null],[32064,"2026-06-07T14:25:54",36,"//а тебе норм ему в соло вести?",32047,null],[32071,"2026-06-07T14:28:23",5,"// присоединяйся",32064,null],[32072,"2026-06-07T14:28:39",36,"//не могу",32071,null],[32078,"2026-06-07T14:29:35",5,"// жаль",32072,null],[32095,"2026-06-07T14:34:10",64,"//ну он вас вывел в лес, там все подойдёте и важные основные части начну давать, вообще ваша ж идея сводно вести вроде? Ну он ничего особо важного крч не сделал почти, просто скип переходной локи устроил",32064,null],[32101,"2026-06-07T14:34:52",5,"// надеюсь все подойдут до четверга",32095,null],[32118,"2026-06-07T14:36:43",36,"//а я тоже хотела поболтать на рынке... Может даже чё нить бы купила",32095,null],[32131,"2026-06-07T14:40:19",64,"//там нет торговцев щас",32118,null],[32134,"2026-06-07T14:40:47",64,"//чи насмешка чи надежда",32101,null],[32137,"2026-06-07T14:41:46",5,"// надежда",32134,null],[32139,"2026-06-07T14:42:07",5,"// напиши тогда этот ивент чтобы мы думали",29484,null],[32140,"2026-06-07T14:42:30",64,"//ну пока они там гоблина ебут как будто можно",32139,null],[32142,"2026-06-07T14:42:55",64,"@Professor_3M653 @elsio28 @Jak_Zak\nКто то владеет великаньим языком?",29484,null],[32145,"2026-06-07T14:44:12",5,"// не",29484,null],[32156,"2026-06-07T14:48:58",64,"шелест в кустах, тяжелые шаги, из тумана вокруг выходит 2 массивные фигуры, каких то диких здоровенных гуманоидов с дубинами (просто ветви большие), ходят бок о бок. Первый талкает второго и что то рычит на великаньем, показывая на лошадей. Второй кладёт ему руку на плечо и рычит в ответ. Они пока просто смотрят на вас\n@Professor_3M653 @elsio28 @Jak_Zak\nВы что то делаете?",29484,null],[32161,"2026-06-07T14:49:59",5,"// о боги",29484,null],[32165,"2026-06-07T14:50:41",5,"Минотавр смотрит на их жесты пытаясь, что они намерены делать. Дружелюбны ли?",29484,null],[32203,"2026-06-07T14:58:49",5,"- Как будто один хочет съесть наших лошадей, а другой отговаривает, - думает вслух Бхагар",29484,null],[32205,"2026-06-07T14:59:13",64,"А, кинь проницательность",32165,null],[32206,"2026-06-07T14:59:19",64,"Щас остальные отпишут кину реакт",29484,null],[32212,"2026-06-07T15:00:48",5,"/r",29484,null],[32222,"2026-06-07T15:02:53",64,"Прорицательность + сколько?",32213,null],[32227,"2026-06-07T15:03:47",5,"/+0",29484,null],[32228,"2026-06-07T15:04:09",64,"все что ты понимаешь — они положили глаз на ваших лошадей, причём оба сразу",32213,null],[32233,"2026-06-07T15:05:54",5,"- Хмм, если они и правда пришли за лошадьми, то я вижу два варианта. Можно накормить их и договориться - может они помогут найти купца. Его жизнь важнее.",29484,null],[32236,"2026-06-07T15:06:28",5,"- Либо можем рвануть от них через лес прямо сейчас. Может закончиться плохо, но это вариант.",29484,null],[32239,"2026-06-07T15:06:58",5,"- Они выглядят опасными, так что вариант убить их выглядит плохо",29484,null],[32242,"2026-06-07T15:07:56",5,"// мне ждать остальных или самому?",29484,null],[32245,"2026-06-07T15:08:11",64,"//лучше подождать, вот этот кусок может быть важным",32242,null],[32248,"2026-06-07T15:08:33",5,"// ок",29484,null],[32249,"2026-06-07T15:08:52",5,"/r d3",29484,null],[32903,"2026-06-07T17:27:58",42,"// я тута",29484,null],[32917,"2026-06-07T17:34:07",5,"// давай читай и высказывай мнение",32903,null],[32918,"2026-06-07T17:35:27",42,"// увы, я великаний не знаю",29484,null],[32920,"2026-06-07T17:36:58",42,"- моя кровь мне шепчет три варианта, либо мы договариваемся, либо их уничтожаем, ну или мы превращемся в блинчики",32239,null],[32921,"2026-06-07T17:39:16",42,"- не доверяю я великанам.. Один такой меня накормил, вырубил и я проснулся в гигантском котле\n°медленно тянется за оружие ожидая другие варианты своей команды°",29484,null],[32922,"2026-06-07T17:40:13",5,"— Думаешь, справимся? — минотавр с сомнением смотрит на великанов.",29484,null],[32923,"2026-06-07T17:41:57",42,"- более чем. Я уверен что ты здоровяк не слабее их, а для нас это будет чудным трофеем и наши действия помогут людям, ибо уверен что они терроризируют людей по близости, а я такое не прощаю..",29484,null],[32926,"2026-06-07T17:43:47",5,"Бхагар убеждён речами тифлинга. Он готов атаковать вместе с союзниками.",29484,null],[32932,"2026-06-07T17:49:26",42,"// кстати я тратил усиленный заговор крови?",29484,null],[32933,"2026-06-07T17:49:38",5,"// когда-то тратил",32932,null],[32934,"2026-06-07T17:49:56",42,"//ок, тогда..",29484,null],[32941,"2026-06-07T17:52:33",42,"°взялся за лезвие ножа и порезал себе ладонь читая заклинание на инфернальном и вся кровь что должна была вытечь на землю испаряется адским пламенем в воздухе°",29484,null],[32943,"2026-06-07T17:52:45",42,"/r 1d4",29484,null],[32946,"2026-06-07T17:53:08",42,"//ладно, чем меньше тем лучше с моим приколом",29484,null],[33413,"2026-06-07T19:43:03",64,"@Professor_3M653 твои действия, догадки может? К скольки ждать? Тут файтинг потенциально",29484,null],[33667,"2026-06-07T22:25:51",36,"//бля простите, но я впринципе говорила до этого \nУ меня завтра экзамен, щас ничего не могу. Надо ложиться спать, высыпаться. Ещё раз извиняйте.",33413,null],[33671,"2026-06-07T22:26:39",64,"Окау, на битву не притендуешь?//",33667,null],[33698,"2026-06-07T22:34:35",36,"//не, битву пропускать не собираюсь \nНе думаю что день задержки сделает вам плоха",33671,null],[33703,"2026-06-07T22:41:17",42,"// ну согласен",29484,null],[33758,"2026-06-07T23:47:12",5,"// ок ждём",29484,null],[34851,"2026-06-08T20:12:10",64,"@elsio28 @Jak_Zak @Professor_3M653 сегодня как?",29484,null],[34854,"2026-06-08T20:12:42",5,"// могу, но малоактивно, параллельно с другим квестом",29484,null],[34856,"2026-06-08T20:13:00",64,"//бля ну если боевка, хзхз",34854,null],[34858,"2026-06-08T20:13:23",64,"//хотя там быстро как будто драться как т",29484,null],[34863,"2026-06-08T20:14:15",5,"// как будто ждём дк",29484,null],[34867,"2026-06-08T20:15:59",10,"Дк в 21 сказала освободится //",29484,null],[34883,"2026-06-08T20:23:32",36,"//ща посуду помою и приду",34867,null],[34884,"2026-06-08T20:23:37",36,"//не шутить!",29484,null],[34901,"2026-06-08T20:32:11",10,"// ДК придет ровно в очко )",29484,null],[34904,"2026-06-08T20:32:47",10,"// знаете как понять время по приходу дк ? Она приходит и наступает очко",29484,null],[34905,"2026-06-08T20:33:14",10,"//приходите на мой уебищный стендап и пинганите когда начнёте я удалю все",29484,null],[35017,"2026-06-08T21:34:37",64,"//пусть останется мы не против",34905,null],[35018,"2026-06-08T21:34:44",64,"//👹👹👹👹👹👹👹",34883,null],[35021,"2026-06-08T21:35:22",64,"//учись, понторезка",34883,null],[35022,"2026-06-08T21:35:37",36,"//я толко написать хотела",35018,null],[35023,"2026-06-08T21:35:40",64,"//я по делам, не меньше чем через пол часа подходите",29484,null],[35024,"2026-06-08T21:36:04",36,"//у меня инет шалит и не грузит МОИ же сообщения",29484,null],[35025,"2026-06-08T21:36:09",36,"//уебок",35023,null],[35030,"2026-06-08T21:36:41",64,"//не тебе же одной посуды мыть 😎",35025,null],[35048,"2026-06-08T21:49:15",64,"@Professor_3M653 @Jak_Zak  @elsio28 к 10 вечера по Москве сможете подойти мы мб сегодня доведем эту штуку?",29484,null],[35050,"2026-06-08T21:49:34",5,"// всё время тут",35048,null],[35051,"2026-06-08T21:49:43",42,"// я щас веду игру",35048,null],[35052,"2026-06-08T21:50:04",36,"//оке",35048,null],[35063,"2026-06-08T21:52:16",64,"//на скока сможешь освободится по 10ти бальной?",35051,null],[35077,"2026-06-08T21:59:40",64,"Герои видят как один из великанов чуть подходит и показывает на лошадь минотавра\n—Еее...—он делает небольшую паузу и явно над чем то задумывается—Мгвз, гррх... Ахг!—внезапно он восклицает что то—Еда, дарить нам ваши еда! Наша не брать вам здоровья!",32162,null],[35081,"2026-06-08T22:00:39",36,"//можешь описать что происходит?",35077,null],[35088,"2026-06-08T22:02:37",64,"//вы заехали в деревню, там минотавр сходил к трактирщику и узнал что Малсер (купец) через лес поехал, минотавр повёл вас в лес и проебал навык выживание, в итоге вы потерялись и до вас доебались два крупных гуманоидообразных существа с дубинами и тупым видом, щас один из них подошёл и сказал это",35081,null],[35095,"2026-06-08T22:04:53",36,"Кью гордо показывает руками чтобы остальные ей не мешали и подходит к ограм\n\n- Моя давать вам вкусный еда, ваша отставать от нас. Так?",35077,null],[35106,"2026-06-08T22:07:30",36,"Все эти слова подпитывала жестами, чтобы те точно поняли",35095,null],[35107,"2026-06-08T22:07:40",64,"Они переглядываются друг между другом, что то рычат на своём, один из них опирается на дубину и смотрит на Кью с высока \n—Еда—показывает на лошадь—не еда трава. Еда мясо. Много еда желание—показывает на тебя—ты маленький, мало еда. Давать много еда, наша идти вон не трогать ваша",35095,null],[35113,"2026-06-08T22:08:28",5,"Минотавр наблюдает за девочкой, готовый к битве.",29484,null],[35116,"2026-06-08T22:09:42",36,"Кью задумалась\n\n- У моя есть вкусны еда. Там есть мяса. Но и трава есть. Моя мочь дать ТОЛЬКО мяса. Ес ваша хотеть",35107,null],[35117,"2026-06-08T22:10:47",64,"полуогры переглянулись между собой, что то порычали, снова, уже чуть более заинтересованно. Тот который с тобой говорил чуть присел и сказал:\n—показать нам!",35116,null],[35119,"2026-06-08T22:17:04",36,"Радостная Кью улыбнулась и побежала к коню за своей сумкой. Которую она ТИПО вытащила оттуда, по факту она её вытащила из себя, затем поковырявшись там она нашла пару порций своей фирменной Кьюфэрии. А после подала им.\n\n- Сама Тролль похвалить эта еда!\n\nГордо произнесла Кью",35117,null],[35120,"2026-06-08T22:17:35",36,"//если я правильно помню то данное блюдо она придумала ДО начала квеста",29484,null],[35121,"2026-06-08T22:18:01",64,"//что это нахй🍺",35119,null],[35122,"2026-06-08T22:18:24",64,"//чучут описание можно я щас, прост не очень понимаю что это реально",29484,null],[35123,"2026-06-08T22:18:32",64,"//типо окей, можно, просто что это",29484,null],[35124,"2026-06-08T22:19:12",5,"// окей, это крутой мув",35119,null],[35125,"2026-06-08T22:19:18",36,"//фирменное блюдо Кью\nза скину рецепт",35123,null],[35126,"2026-06-08T22:20:04",9,"//Тебе бы скинуть еще соо где троль это ел, для наглядности. Но там не факт что остальных его сородичей в конвульсиях не скрутит...",35125,null],[35127,"2026-06-08T22:20:21",5,"// минусы?",35126,null],[35128,"2026-06-08T22:20:34",64,"//травануть огров звучит как план",35126,null],[35129,"2026-06-08T22:22:09",9,"//Им будет вкусно ^^",35128,null],[35130,"2026-06-08T22:22:24",53,"//читаю название и вижу этосообщение",35129,null],[35131,"2026-06-08T22:22:47",64,"//в целом он пока ближе всех к разгадке",35130,null],[35132,"2026-06-08T22:24:25",36,"Это было, молоко, с мороженным, шоколадом, вином, виски, пивом, яблоками, 4 мешками 5кг сахара и 2 мешками 5 кг соли. Затем перемешала кепя это все на большом огне, а после добавила своих грибочков, заранее мелко нарезав и смешав в блендере две отдельные порции (одна в блендер, другая нет). Грибы с её тела вызывают галлюцинации даже после варки, а так же снимают стресс, напряжение и т.д. законный сильный наркотик. Потом вспомнила про бананы и моллюска. После чего тут же их туда закидала.Пачка рациона с мясом человека и слюнями Кью; Слезы Кью, которые придали блюду интересный расскрасс ввиде круговорота из синего, жёлтого, зелёных и красных цветов. Теперь моя еда усиливает глюки, расскрасывает глаза, содержит обилие дофомина, а так же даёт чувство полёта, хотя тело никак не меняется. Выглядит как мороженное так как загустело из за спор. Затем украсила листами мяты и клубникой. Пахло это сыром, молоком, хлебом? Мясом людей(это чуют только людоеды), Фруктами и ягодами..",35123,null],[35134,"2026-06-08T22:26:09",64,"//тщщщщ, ни слова больше, я увидел наркотики, кончу Кью и мясо человека в одном составе",35132,null],[35139,"2026-06-08T22:29:21",42,"// хз, у меня прям активная фаза",35063,null],[35141,"2026-06-08T22:29:45",64,"//ну щас мб дк их отгонит",35139,null],[35143,"2026-06-08T22:29:51",64,"//тебя ждать?",35139,null],[35145,"2026-06-08T22:30:18",36,"//если они это едят то пусть кинут спас тела",35141,null],[35147,"2026-06-08T22:30:46",64,"//проеб это уход в мир иной?",35145,null],[35158,"2026-06-08T22:33:28",64,"Огриллион с подозрением смотрит на это блюдо и, перед тем как есть это пару раз тыкает пальцем, стоит отметить невероятно грязным пальцем, который одному богу известно где побывал. А после неаккуратно проталкивает это себе в глотку. \n—бхгр, бхгар... *звуки неразборчивой речи великана с чавканьем*",35119,null],[35159,"2026-06-08T22:33:32",64,"/roll 1d20+2",29484,null],[35161,"2026-06-08T22:33:42",64,"@Professor_3M653 он въебывает спас?",35160,null],[35168,"2026-06-08T22:35:27",36,"//ессс",35161,null],[35169,"2026-06-08T22:35:43",9,"//Я хз квкой там спас, на ядах обычно 10, как дм решай",35161,null],[35170,"2026-06-08T22:36:09",64,"//похуй пусть въебет мне щас ещё файтить их всех без 1... Чёт не",35169,null],[35172,"2026-06-08T22:36:20",36,"//это не яд и на обычном яде спас 10",35169,null],[35185,"2026-06-08T22:37:41",5,"// ну я тут для файта",35170,null],[35192,"2026-06-08T22:39:35",64,"Лишь проглотил Огриллион сие явство и пал на земь, закатив глаза и ударясь в конвульсиях, ему явно очень очень херово от этого мессива. Всю эту картину видит второй полуогр, бьёт первого по голове, чтобы тот не мучался и говорит\n—Еда, много. Большой как 1 лошадь еда и ещё левая кусок лошадь.",35119,null],[35193,"2026-06-08T22:39:39",64,"/roll@roll_bot",29484,null],[35195,"2026-06-08T22:39:48",64,"//пизда и второму щас будет",29484,null],[35198,"2026-06-08T22:41:17",36,"//он тоже попробовал? Кайф",35195,null],[35205,"2026-06-08T22:42:14",64,"//не, он не пробовал, он подумал просто что у второго судороги не от этой еды",35198,null],[35207,"2026-06-08T22:42:35",64,"//у первого хз, похуй на порядок",29484,null],[35208,"2026-06-08T22:43:03",36,"- Хараша, хараша. Но эта еда сытна. Твоя пробовать, Твоя понравится",35192,null],[35211,"2026-06-08T22:44:46",64,"//даёшь типо порцию тоже?",35208,null],[35212,"2026-06-08T22:44:55",64,"/roll@roll_bot",29484,null],[35214,"2026-06-08T22:45:02",64,"Та же хуйня",29484,null],[35220,"2026-06-08T22:46:28",9,"//Зато им было оооочеееенььь вкусссннооооо",29484,null],[35221,"2026-06-08T22:46:31",64,"Полуогр жадно хавает это мессиво явно неземного происхождения и тоже падает дрожа в конвульсиях. Выходит путь свободен? Два неедеспособных полуогра лежат в конвульсиях. Лошади у вас",29484,null],[35223,"2026-06-08T22:46:43",64,"//а хуй его знает, мб у них корона",35220,null],[35229,"2026-06-08T22:47:29",5,"Бхагар подходит к ограм и тыкает алебардой, чтобы убедиться, что они мертвы",29484,null],[35235,"2026-06-08T22:49:13",36,"- Ну... Теперь я знаю что ограм не нравится моя еда)\n\nПожала плечами, превратила руки в когти и стала вспарывать им брюхи словно это мешки с кортошкой. перерезать им глотки и отрывать конечности паралельно поедая сладкие органы по типу сердца и лёгких",35221,null],[35240,"2026-06-08T22:50:31",5,"Увидев эту отвратительную картину, минотавр плюёт под ноги и говорит.\n\n— Так и знал, что ты не девочка, а отвратительное чудовище",35235,null],[35241,"2026-06-08T22:50:38",64,"полуогры никак не реагируют на ваши касания. Мм, можно идти?",35229,null],[35242,"2026-06-08T22:50:41",64,"/roll@roll_bot",29484,null],[35244,"2026-06-08T22:50:57",64,"Да, идите, не будет ебаки 😞",29484,null],[35246,"2026-06-08T22:51:14",5,"// идём, пусть чудище ведёт раз так",29484,null],[35247,"2026-06-08T22:51:40",64,"//и я уебок после такой хуйни да?",35235,null],[35249,"2026-06-08T22:52:01",36,"Словно сосиски всасывает в себя тонкую кишку глядя на минотавра\n\n- Будь я монстром, сожрала бы тебя пока ты спал. А так я просто своеобразный падальщик. А они моя добыча",35240,null],[35252,"2026-06-08T22:52:18",36,"//ты на пол часика перевёл",35247,null],[35260,"2026-06-08T22:54:00",64,"ты вспарываешь свежие туши полуогров без битвы, так, будто они мясо для разделывания. Ты ешь их внутренности, почти все. Но кажется, есть свеже отравленные туши не лучшая идея? Странный привкус у плоти и некоторых органов... Кинь спас по телу небольшой там",35235,null],[35261,"2026-06-08T22:54:18",64,"//вообще пиздато каки огра хавать",35249,null],[35262,"2026-06-08T22:54:30",36,"//в тонкой кишке нет говна",35261,null],[35263,"2026-06-08T22:54:41",36,"//калловые массы образовываются в толстой",29484,null],[35264,"2026-06-08T22:54:47",64,"//у тебя какие то сопротивления иммунитеты к отравлению есть?",35262,null],[35265,"2026-06-08T22:55:28",36,"//КОнечно) Иначе какой из меня падольщик?",35264,null],[35267,"2026-06-08T22:56:03",64,"//...китайский?",35265,null],[35268,"2026-06-08T22:56:09",64,"//лан похуй прикола ради кинь",29484,null],[35271,"2026-06-08T22:56:29",36,"// Бля.. Прикинь я его провалю чисто потому что у меня нет владения?",35267,null],[35272,"2026-06-08T22:56:40",36,"/r +d20+3",29484,null],[35274,"2026-06-08T22:56:45",36,"//крит",35273,null],[35282,"2026-06-08T23:01:17",64,"тебе могло бы быть очень плохо от твоих действий, но тебе все равно от того что ты съела. Чтож, никакой морали из этого столкновения с полуограми не было изъято. Вы выдвигаетесь дальше... Едете по дремучему, злому и страшному лесу, в поисках... Быть может следов, быть может самого Малсера. В общем, полуогры позади. Вокруг что то носится, неистово быстро, и с тяжёлыми шагами. Нечто убежало в сторону убитых и освежованных полуогров, а вы двигаетесь дальше. Кто лидер и направляет вас? @Professor_3M653 @elsio28 @Jak_Zak",35273,null],[35283,"2026-06-08T23:01:23",64,"//вот это я хорош",29484,null],[35284,"2026-06-08T23:01:29",64,"// @Professor_3M653 @elsio28 @Jak_Zak",29484,null],[35287,"2026-06-08T23:01:57",5,"// я сзади и пристально слежу за маленьким отродьем",29484,null],[35288,"2026-06-08T23:02:14",64,"// @Professor_3M653 у тя скок к выживанию бонус?",29484,null],[35289,"2026-06-08T23:02:25",36,"//я конечна",35282,null],[35290,"2026-06-08T23:02:35",36,"//ээээ\nща гляну",35288,null],[35291,"2026-06-08T23:02:48",64,"//ты буквы местами перепутала",35289,null],[35292,"2026-06-08T23:02:53",64,"//ну кинь там выживание",35290,null],[35294,"2026-06-08T23:03:31",36,"//приемущества?",35292,null],[35303,"2026-06-08T23:04:11",64,"//какие от чего что",35294,null],[35307,"2026-06-08T23:04:33",36,"//просто спросила....",29484,null],[35308,"2026-06-08T23:04:38",36,"/r +5",29484,null],[35313,"2026-06-08T23:05:06",64,"//ясно",29484,null],[35314,"2026-06-08T23:05:13",36,"//ПХЫХХЫ",35312,null],[35318,"2026-06-08T23:06:41",64,"вы мотаете ещё круги по лесу... Второй круг... Третий... Потерялись, круто че. А тварь вокруге рыскает. Замечаешь что деревья будто с ума сошли и в разные стороны показывают. А земля... Ни следа Малсера, будто и не заезжал он в лес. Но вам ведь сказали?...",29484,null],[35319,"2026-06-08T23:06:47",64,"1/3\n0/3",29484,null],[35320,"2026-06-08T23:06:55",64,"//кинь ещё выживание",35314,null],[35321,"2026-06-08T23:07:12",5,"// можно я поищу следы?",29484,null],[35323,"2026-06-08T23:07:30",64,"//ебашь",35321,null],[35324,"2026-06-08T23:07:36",5,"/r +2",29484,null],[35326,"2026-06-08T23:07:49",64,"//не лучше",35325,null],[35327,"2026-06-08T23:08:10",36,"/r +5",35320,null],[35329,"2026-06-08T23:08:12",5,"// зачем делать сл 15 на поиск дороги",29484,null],[35330,"2026-06-08T23:08:36",64,"ты берёшь инициативу над следами в свои руки и ведёшь пачку в ещё большую чащу, звуки страшнее, а света меньше...",35324,null],[35331,"2026-06-08T23:08:41",64,"//во",35328,null],[35335,"2026-06-08T23:10:00",64,"хм.. След, кажется от повозки, он ведёт в какую то сторону, если присмотреться к окружению то можно понять что на север, к выходу из леса. Ты нашла след Малсера и ведёшь пачку по нему. Деревья указывают путь а рык твари дальше чем нужно, вроде все норм",35327,null],[35336,"2026-06-08T23:10:10",36,"Кью заметила как её товарищ делает мягко говоря полную хуйню и толкнув его в сторону взяла всё в свои руки",35330,null],[35337,"2026-06-08T23:10:15",64,"//это нормальная сложность по книжке",35329,null],[35338,"2026-06-08T23:10:33",64,"2/3\n1/3",29484,null],[35340,"2026-06-08T23:10:40",64,"//ещё раз с приемуществом",35336,null],[35343,"2026-06-08T23:11:03",36,"/r +d20+5",35340,null],[35345,"2026-06-08T23:11:08",64,"Ебейше",29484,null],[35349,"2026-06-08T23:12:30",64,"Вы совсем близко, видны и следы его копыт лошади. Вы подъежаете к какой то тропе возле большого бугорного хребта(просто холмы длинные вдоль дороги), кажется он выехал на неё и ехал по ней. Ещё разок",29484,null],[35395,"2026-06-08T23:21:25",36,"//так же с приемом?",35349,null],[35398,"2026-06-08T23:21:44",36,"/r +d20+5",29484,null],[35403,"2026-06-08T23:22:36",64,"//мечта",29484,null],[35406,"2026-06-08T23:22:54",64,"// @Jak_Zak а ты когда сможешь на боевку минуток 20 уделить?",29484,null],[35424,"2026-06-08T23:26:05",64,"следы обрываются... Вы у въезда в основание какой то пещеры в холмах посреди леса. Около входа в пещеру валяются остатки какой то крупной копытной скотины... Что то похожее на лошадь может быть? Видно колесо повозки и какие то следы. Не следы человека, нога сильно больше, тяжелее и когтистее. Земля местами как будто порублена а следы крови не ушли до конца. Что же здесь творится..?",35399,null],[35438,"2026-06-08T23:29:19",36,"- Я щас скажу немного бред... Либо оборотень, либо его приманила и сожрала разумная дрянь...\n\nПосмотрела на товарищей\n\n- Каков план мои дорогие?",35424,null],[35449,"2026-06-08T23:31:09",64,"//там тележка сломаная его ещё да",35446,null],[35453,"2026-06-08T23:32:28",5,"// осматриваю следы, чтобы опознать существо природа?",35438,null],[35456,"2026-06-08T23:33:15",64,"//ну пусть, окау, природу кинь",35453,null],[35463,"2026-06-08T23:33:44",64,"//я тебе ток его вид скажу и размер с массой",29484,null],[35464,"2026-06-08T23:33:51",5,"/r -1",29484,null],[35476,"2026-06-08T23:38:41",64,"это Великан, скорее всего большой, по следам ты мог определить его массу, около 450 кг, и рост, около 3.5 метров. Следы показывают что он кого то бил с использованием рубящих предметов большого, даже по меркам этого существу, размера. Тут же есть и следы, судя по всему, Малсера, бежавшего от сюда и лошади, которая пыталась откуда то выбраться. Ну и следы телеги его",35464,null],[35488,"2026-06-08T23:40:12",5,"— Это великан, раза в 2 больше меня. И следы купца тут же, надо идти по ним да поспешить!",35476,null],[35494,"2026-06-08T23:40:53",64,"следы обрываются недалеко от повозки... Кинь внимательность",35488,null],[35509,"2026-06-08T23:42:51",5,"/r +2",29484,null],[35523,"2026-06-08T23:45:02",64,"следы обрываются и все вроде, ну, ты по крайней мере ничего лишнего не видишь",29484,null],[35553,"2026-06-08T23:49:05",5,"*жду спутников, ожидая их помощи*",29484,null],[35566,"2026-06-08T23:50:58",36,"- ну то что великан мы поняли, а следы что ты разглядывал что дали?",35553,null],[35598,"2026-06-08T23:54:41",5,"— Малсер бежал, но следы внезапно кончились",35566,null],[35605,"2026-06-08T23:55:35",36,"//точно малсер? Я по словам ДМ поняла что ушёл великан, а малсер в пщеере",35598,null],[35607,"2026-06-08T23:56:05",5,"//непонятно дм написал",35476,null],[35608,"2026-06-08T23:56:21",5,"// по идее малсера",35488,null],[35609,"2026-06-08T23:56:42",64,"//кого что",35605,null],[35611,"2026-06-08T23:57:08",64,"//ну вам в пещеру да, бля чёт криво мешанина, доимпровизировал",29484,null],[35612,"2026-06-08T23:57:21",5,"// ок го в пещеру",29484,null],[35635,"2026-06-09T00:04:01",64,"//бля ну щас третий напишет",29484,null],[35636,"2026-06-09T00:04:21",64,"//я не могу допустить чтоб он все точки важные скипнул",29484,null],[35829,"2026-06-09T00:50:46",64,"//ебейше конечно",29484,null],[35830,"2026-06-09T00:51:11",64,"// @elsio28 @Professor_3M653 @Jak_Zak завтра будет минуток 30 на закончить?",29484,null],[35831,"2026-06-09T00:51:42",5,"// конечно будет",29484,null],[35832,"2026-06-09T00:52:06",64,"//вай лев тигр брат легенда ежжи ты",35831,null],[35833,"2026-06-09T00:52:25",42,"// конечно , я уже закончил игру",35830,null],[35834,"2026-06-09T00:52:45",5,"// можете сделать что там надо и начать бой",29484,null],[35835,"2026-06-09T00:52:51",5,"// я завтра утром появлюсь",29484,null],[35836,"2026-06-09T00:53:23",64,"//третью щас поймать бы с которой вы как магниты одного полюса отталкиваетесь будто",35833,null],[35841,"2026-06-09T09:37:26",64,"// @elsio28 @Professor_3M653 @Jak_Zak к скольки вы свободны все?",29484,null],[35843,"2026-06-09T09:42:06",42,"// я уже на весь день",29484,null],[35844,"2026-06-09T10:07:46",36,"//к вечеру",35841,null],[35851,"2026-06-09T11:21:34",64,"//на сколько к вечеру?",35844,null],[35852,"2026-06-09T11:24:13",36,"//ХЫЗЫ",35851,null],[35853,"2026-06-09T11:24:50",64,"//я к 10 вечера по Москве ваши души бронирую тогда?",35852,null],[35854,"2026-06-09T11:25:42",36,"//можна",29484,null],[35855,"2026-06-09T11:43:31",5,"// весь день",35841,null],[35856,"2026-06-09T11:55:08",64,"// @elsio28 @Professor_3M653 @Jak_Zak к 10 вечера по Москве подходите доиграем сегодня за часик, может меньше, там в конце вкусняшки 2 есть",29484,null],[35857,"2026-06-09T12:04:12",42,"// оке",35856,null],[35981,"2026-06-09T13:58:25",64,"//гайс а я правильно понял вы спешиваетесь с лошадей чи вы местность вокруг прям на конях смотрели? @Professor_3M653 @elsio28",29484,null],[36005,"2026-06-09T14:08:20",5,"// да, я спешился",35981,null],[36008,"2026-06-09T14:14:23",64,"//окау",36005,null],[36009,"2026-06-09T14:14:43",36,"//я на конях\n\nСКАЧИ СКАЧИ МОЙ ПОНИК! ТЫГЫДЫК ТЫГЫДЫК ТЫГЫДЫК",35981,null],[36016,"2026-06-09T14:19:49",64,"//на конЯХ. Окей окей",36009,null],[36029,"2026-06-09T14:23:03",36,"//на двух понях",36016,null],[36101,"2026-06-09T15:00:03",36,"//Чисто Кью:",36029,null],[36269,"2026-06-09T16:04:27",64,"//ты уверена что делаешь это?",36029,null],[36278,"2026-06-09T16:07:36",36,"//уверена, а что?",36269,null],[36279,"2026-06-09T16:08:17",36,"//надо же как то повыебываться",29484,null],[36283,"2026-06-09T16:10:00",42,"// это да",36279,null],[36310,"2026-06-09T16:31:09",64,"//оке окей, ничего наверное👹",36278,null],[36322,"2026-06-09T16:34:57",42,"// предлагаю выдать преимущество за то что друид и может кооперироваться с лошадьми",36310,null],[36327,"2026-06-09T16:35:46",36,"//ФАКТ",36322,null],[36328,"2026-06-09T16:36:20",64,"//✅✅",36322,null],[36329,"2026-06-09T16:36:46",64,"//побойтесь ка бога как бы оно хуже не стало😨",29484,null],[36379,"2026-06-09T18:52:25",64,"// @elsio28 @Professor_3M653 @Jak_Zak отпишите как свободны будете мб раньше начнём",29484,null],[36381,"2026-06-09T19:04:28",36,"//я могу впринципе, ток переодически буду пропадать",29484,null],[36407,"2026-06-09T20:12:46",5,"// ну я тут",29484,null],[36408,"2026-06-09T20:13:01",64,"// @Jak_Zak",29484,null],[36433,"2026-06-09T20:41:51",42,"// Да-да",29484,null],[36434,"2026-06-09T20:43:54",42,"// но я смогу только после 21:30",29484,null],[36435,"2026-06-09T20:45:32",64,"//мы к 22:00 тогда как и хотели",36434,null],[36444,"2026-06-09T21:27:39",36,"// @Jak_Zak \n@detahsola \n@elsio28 \nМы обязаны сегодня закончыт",29484,null],[36445,"2026-06-09T21:27:50",5,"// го тогда",29484,null],[36446,"2026-06-09T21:28:07",36,"//мне помытса нада",36445,null],[36447,"2026-06-09T21:28:21",36,"//а чтобы помытса нада дождаться пока крем начнет сжечься",29484,null],[36448,"2026-06-09T21:28:33",64,"//чего что кто",36447,null],[36449,"2026-06-09T21:28:39",64,"//мы закончим",36444,null],[36450,"2026-06-09T21:29:05",36,"//кого ебать? Зачем ебать? Почему ебать?",36448,null],[36451,"2026-06-09T21:29:57",36,"//я устала ждать крем, в пизду. Пойду мыться",29484,null],[36452,"2026-06-09T21:30:11",64,"//пол часа тоби",36451,null],[36453,"2026-06-09T21:30:17",36,"//сяб",36452,null],[36455,"2026-06-09T22:01:44",36,"//ну я тута",29484,null],[36456,"2026-06-09T22:02:37",64,"//пару минут гайс я ем",29484,null],[36457,"2026-06-09T22:02:42",64,"// @elsio28 @Jak_Zak",29484,null],[36458,"2026-06-09T22:03:48",5,"// тут",29484,null],[36459,"2026-06-09T22:05:30",36,"//а я мочалку мою",36456,null],[36460,"2026-06-09T22:06:25",64,"//ну мы сегодня закончим в любом случае ибо я ещё квест хотел бы по хорошему открыть там на боевку в базе, как я люблю да, но с возможностью в социалку да",29484,null],[36461,"2026-06-09T22:06:36",64,"//короче щас, через минут 5 ещё",29484,null],[36462,"2026-06-09T22:06:41",5,"// я только за",29484,null],[36463,"2026-06-09T22:14:26",64,"//брад время уже после 21:30",36434,null],[36464,"2026-06-09T22:19:03",36,"//так и 5 минут уже давно прошло",36463,null],[36465,"2026-06-09T22:19:03",64,"Итак, герои у входа в пещеру осмотрели почти все что можно. Из пещеры, скрытой лианами доносятся тяжелые шаги и скрежет метала по камню. Герои, что вы делаете? \n@Professor_3M653 @Jak_Zak @elsio28",29484,null],[36466,"2026-06-09T22:19:43",36,"- У кого нибудь есть ловушки? Калтропы там?",36465,null],[36467,"2026-06-09T22:20:17",5,"Минотавр не отвечает. Он стоит у входа и зорко глядит то внутрь, то на девочку",29484,null],[36468,"2026-06-09T22:20:26",36,"- Ну спасибо...",36467,null],[36469,"2026-06-09T22:20:29",64,"//ясно",29484,null],[36470,"2026-06-09T22:20:44",5,"// а что с монстрами говорить",29484,null],[36471,"2026-06-09T22:21:18",36,"//иди нафиг....",36470,null],[36472,"2026-06-09T22:23:08",5,"// что ждём зака?",29484,null],[36473,"2026-06-09T22:23:20",36,"//ща ещё заклы свои проверю",36472,null],[36474,"2026-06-09T22:23:46",64,"из пещеры, срывая лозы выходит здоровенный огр, на его голове красуется шлем из лёгких металлов, а плечо, грудь и бедра украшены и защищены деревянными вкладками. В его руках красуется здоровенный меч, который он волочит по земле. После чего резко заносит его за голову, готовясь к удару, топает ногой и издаёт страшный рев!",29484,null],[36475,"2026-06-09T22:23:49",64,"//щас",29484,null],[36476,"2026-06-09T22:24:01",36,"//да ну бля... Ну дай время на подготовку...",36474,null],[36477,"2026-06-09T22:24:10",64,"/roll 3d20",29484,null],[36479,"2026-06-09T22:24:22",64,"Бля ну там 1 лошадка испугалась",29484,null],[36480,"2026-06-09T22:24:26",64,"И пытается сбежать",29484,null],[36481,"2026-06-09T22:24:38",64,"Кинь спас ловкости чтоб на лошадях удержаться",36476,null],[36482,"2026-06-09T22:24:41",36,"//это не моя лошадь",36480,null],[36483,"2026-06-09T22:24:44",36,"//у меня две",29484,null],[36484,"2026-06-09T22:24:46",5,"Минотавр бросается к лошади, чтобы остановить её",29484,null],[36485,"2026-06-09T22:24:49",36,"//и те две мои крутые",29484,null],[36486,"2026-06-09T22:24:56",36,"//мы все в очках",29484,null],[36487,"2026-06-09T22:25:01",36,"//черных",36486,null],[36488,"2026-06-09T22:25:06",64,"//ок, сочту за помощь",36484,null],[36489,"2026-06-09T22:25:08",64,"/roll@roll_bot",29484,null],[36491,"2026-06-09T22:25:15",64,"Да похуй смогла крч",29484,null],[36492,"2026-06-09T22:25:23",64,"Инициатива",29484,null],[36493,"2026-06-09T22:25:30",36,"//что смогла? Кто смогла? Куда смогла?",36491,null],[36494,"2026-06-09T22:25:35",36,"//а ладно...",36492,null],[36495,"2026-06-09T22:25:39",64,"//лошади свободно действуют или ты под контролем их держишь?",36487,null],[36496,"2026-06-09T22:25:40",5,"// я лошадь останавливал",29484,null],[36497,"2026-06-09T22:25:48",64,"//лошадь не испугаться",36493,null],[36498,"2026-06-09T22:25:53",64,"//ты смог молодец",36496,null],[36499,"2026-06-09T22:26:04",36,"Я если что в этот момент наложила заклинание на посох и теперь из его Конча башка дракона торчит серебренная",36465,null],[36500,"2026-06-09T22:26:30",36,"//под моим контролем... Разговор с животными на друидическом",36495,null],[36501,"2026-06-09T22:26:42",64,"//это чуть баффнутый на кд и урон огр, ну и с хп чуть больше и... Считайте огр ++ на 3 ПО",29484,null],[36502,"2026-06-09T22:26:51",64,"//окей",36500,null],[36503,"2026-06-09T22:27:27",64,"/roll@roll_bot",36492,null],[36505,"2026-06-09T22:27:33",5,"// 3? норм вообще?",36501,null],[36506,"2026-06-09T22:27:42",5,"//надо ещё героя",29484,null],[36507,"2026-06-09T22:27:47",5,"/r +1",29484,null],[36509,"2026-06-09T22:27:48",36,"/r +2",29484,null],[36511,"2026-06-09T22:27:52",64,"//да похуй там не сложно, у меня в планах было 2 твари 2 ПО",36505,null],[36512,"2026-06-09T22:27:57",36,"//mmmmmmm",36510,null],[36513,"2026-06-09T22:27:58",64,"//а тут 1",29484,null],[36514,"2026-06-09T22:28:22",64,"Бхагар 17\nОгр 17\n Кью 5\nЖакио (в конце очереди)",29484,null],[36516,"2026-06-09T22:29:54",64,"Вот актуальная позиция ща",29484,null],[36517,"2026-06-09T22:29:54",5,"// сколько до огра?",29484,null],[36518,"2026-06-09T22:30:20",64,"//дотянешься",36517,null],[36519,"2026-06-09T22:30:28",64,"//по прямой 30",29484,null],[36520,"2026-06-09T22:30:29",36,"//чё за белая Конча рядом с ним?",36516,null],[36521,"2026-06-09T22:30:37",64,"//косточки лошади",36520,null],[36522,"2026-06-09T22:31:02",36,"//он если что не на лошади",36519,null],[36523,"2026-06-09T22:31:14",5,"— Мне это совсем не нравится.\n\nМинотавр отходит за повозку и готовится уклоняться.",29484,null],[36524,"2026-06-09T22:31:20",64,"//да",36522,null],[36525,"2026-06-09T22:31:26",36,"//.....",36523,null],[36526,"2026-06-09T22:31:26",64,"//Океееееей",36523,null],[36527,"2026-06-09T22:31:32",64,"//океннеееннееееейей",29484,null],[36528,"2026-06-09T22:32:10",36,"//моя Гло с 1 хитом и то пользы больше сделает\n\n(Она в таком положении боссу руки оторвала и мне приделала)",36527,null],[36530,"2026-06-09T22:32:44",36,"//ну.... Ход огра",36529,null],[36531,"2026-06-09T22:33:02",36,"//Кью гордо и бесстрашно стоит на двух таких же бесстрашных лошадях с палкой в руках",29484,null],[36532,"2026-06-09T22:33:24",36,"На голове чаша что облеплена цветами и лозами",36531,null],[36533,"2026-06-09T22:33:38",64,"Огр устремляется в сторону Кью и совершает атаку своим здоровенным, двух метровым мечом с полного размаха",29484,null],[36534,"2026-06-09T22:33:47",64,"/roll 1d20+6",29484,null],[36536,"2026-06-09T22:33:51",64,"Еб твою мать",29484,null],[36537,"2026-06-09T22:33:53",36,"//попал",36535,null],[36538,"2026-06-09T22:33:59",64,"/roll 3d8+4",29484,null],[36540,"2026-06-09T22:34:06",64,"Μ",29484,null],[36541,"2026-06-09T22:34:14",64,"На 2 удара",29484,null],[36542,"2026-06-09T22:34:20",36,"//это по бедняжке Кью или по лошадям?",36539,null],[36543,"2026-06-09T22:34:22",5,"// я бы уже умер",29484,null],[36544,"2026-06-09T22:34:25",64,"По Кью",36542,null],[36545,"2026-06-09T22:34:34",64,"Это очень опасно я так умер однажды",36543,null],[36546,"2026-06-09T22:34:44",36,"//Спас силы/ловкости чтобы удержаться на конях?",36544,null],[36547,"2026-06-09T22:35:21",64,"//да похуй пусть стоит, не толкал же",36546,null],[36548,"2026-06-09T22:35:29",36,"//оке",36547,null],[36549,"2026-06-09T22:35:38",36,"//дайте 5 минут",29484,null],[36550,"2026-06-09T22:36:18",64,"Удар довольно чётко ложится на Кью, чуть ли не разрубая ее пополам, но она жива, и, кажется, готова мстить... Ход Кью",29484,null],[36551,"2026-06-09T22:36:36",64,"//Ну он чуть сложнее среднего да",29484,null],[36552,"2026-06-09T22:37:14",64,"// @Jak_Zak брат ты свободен же? Они как будто умрут если не поможешь там",29484,null],[36553,"2026-06-09T22:40:02",5,"// он рил нужен, иначе ярость не прокнуть",29484,null],[36554,"2026-06-09T22:41:34",64,"//я вам не дам умереть ребятки просто знайте",36553,null],[36555,"2026-06-09T22:44:05",36,"//всё\nя тут",29484,null],[36556,"2026-06-09T22:44:38",64,"//это круто твой ход",36555,null],[36557,"2026-06-09T22:46:30",36,"Кью сжимает покрепче свой посох. Пока тот начинает светится\n\n(Я вряд-ли смогу опутать его, он слишком сильный. Да и смысла нет, у меня товарищи не собираются мне помогать, так что... ОСТАЁТСЯ ЛИШЬ ОДНО!!!)\n\n- ПОЛУЧИ ТВАРЬ!\n\nКью посохом словно битой замахивается и бьёт огра по морде",36550,null],[36558,"2026-06-09T22:46:52",64,"Кидай",36557,null],[36559,"2026-06-09T22:47:12",36,"//кидаю",36558,null],[36560,"2026-06-09T22:48:23",36,"/r d20+6",29484,null],[36562,"2026-06-09T22:48:31",64,"Попала",29484,null],[36563,"2026-06-09T22:48:31",36,"//попадание",36561,null],[36564,"2026-06-09T22:48:32",64,"Урон",29484,null],[36565,"2026-06-09T22:49:26",36,"/r d8+3+d6",29484,null],[36567,"2026-06-09T22:49:42",64,"М",29484,null],[36568,"2026-06-09T22:49:44",64,"Ммммм",29484,null],[36569,"2026-06-09T22:50:00",36,"после удара спору вокруг стали гораздо гуще и направились прямяком в огра",29484,null],[36570,"2026-06-09T22:50:10",64,"О эт что",36569,null],[36571,"2026-06-09T22:50:27",36,"//особенность круга",36570,null],[36573,"2026-06-09T22:50:58",36,"пусть чел спас тела кинет",36566,null],[36574,"2026-06-09T22:51:15",64,"//а там сущность симбиотическую принять не? Лан",29484,null],[36575,"2026-06-09T22:51:18",64,"/roll@roll_bot",29484,null],[36579,"2026-06-09T22:51:31",64,"14",36573,null],[36580,"2026-06-09T22:51:38",64,"А прошёл 1 хуй вроде",29484,null],[36582,"2026-06-09T22:51:51",64,"Ой бля, кого я вам дал то",29484,null],[36583,"2026-06-09T22:52:38",36,"/r d4+d4 некротикой",36579,null],[36585,"2026-06-09T22:53:06",64,"Окей это все?",29484,null],[36586,"2026-06-09T22:53:11",36,"/r d6 и ещё некротикой за удар посохом (забыла добавить)",29484,null],[36589,"2026-06-09T22:53:32",64,"Ну неплохо, хода за 3 ебнете",29484,null],[36590,"2026-06-09T22:53:33",36,"Я верхом на конях отступаю влево",36585,null],[36591,"2026-06-09T22:53:51",64,"провоцированная атака по лошади ближе к огру",36590,null],[36592,"2026-06-09T22:53:54",64,"На скок влево",29484,null],[36593,"2026-06-09T22:53:56",64,"/roll@roll_bot",29484,null],[36595,"2026-06-09T22:54:00",64,"Пизда ей",29484,null],[36596,"2026-06-09T22:54:21",36,"сюда куда та",36516,null],[36597,"2026-06-09T22:54:35",64,"/roll@roll_bot 3d8+4",36591,null],[36599,"2026-06-09T22:55:18",64,"Взмах меча и одна из лошадей рубится на 2 части по диагонали",29484,null],[36600,"2026-06-09T22:55:19",5,"// уже было д6 ведь?",36566,null],[36601,"2026-06-09T22:55:31",64,"Там спелл ещё вроде",36600,null],[36603,"2026-06-09T22:55:51",36,"//так... у меня 22 хита\nзапомнили",29484,null],[36604,"2026-06-09T22:56:18",36,"//там от круга приколюху забыла",36600,null],[36605,"2026-06-09T22:56:31",5,"// а первое д6 от чего?",36604,null],[36606,"2026-06-09T22:56:37",36,"//вместа дикого облика которая используется",29484,null],[36608,"2026-06-09T22:57:21",36,"//от заклинания драконий удар, первое д6 холодом",36605,null],[36610,"2026-06-09T22:57:26",36,"//второе некротикой",29484,null],[36611,"2026-06-09T22:57:37",64,"Бля вот хуй знает че там Жакио умеет",36609,null],[36613,"2026-06-09T22:57:52",5,"// ну лошадь убили уже норм",29484,null],[36614,"2026-06-09T22:57:56",5,"// хоть ярость будет",29484,null],[36615,"2026-06-09T22:58:26",36,"//а сколько я в итоге сняла ему палкой?",36611,null],[36617,"2026-06-09T22:58:37",64,"//достойно так",36615,null],[36618,"2026-06-09T22:59:04",64,"Жакио в ахуе спешивается и отходит стреляя в огра",29484,null],[36619,"2026-06-09T22:59:06",64,"/roll@roll_bot",29484,null],[36623,"2026-06-09T22:59:12",64,"Хоть кубы не руки",29484,null],[36624,"2026-06-09T22:59:13",64,"Раки",29484,null],[36626,"2026-06-09T22:59:20",64,"/roll@roll_bot 1d8+3",29484,null],[36628,"2026-06-09T22:59:25",64,"Нормально зарядил",29484,null],[36630,"2026-06-09T22:59:58",64,"@elsio28 твой ход",29484,null],[36631,"2026-06-09T23:01:21",5,"Увидев, что огр убил лошадь, Бхагар пришёл в ярость. Он побежал к врагу, обошёл его сзади и нанёс удар алебардой прямо по башке.",29484,null],[36632,"2026-06-09T23:01:30",5,"// есть окружение?",29484,null],[36633,"2026-06-09T23:01:39",64,"//ебашь да",36632,null],[36634,"2026-06-09T23:01:43",64,"//приемущество там",29484,null],[36635,"2026-06-09T23:02:03",5,"/r +d20+6",29484,null],[36637,"2026-06-09T23:02:09",64,"Попал",29484,null],[36638,"2026-06-09T23:02:19",5,"/r d10+4+2",29484,null],[36640,"2026-06-09T23:02:28",64,"Норм",29484,null],[36641,"2026-06-09T23:02:32",64,"Дохнет маленький уже",29484,null],[36642,"2026-06-09T23:02:37",64,"Он жив",29484,null],[36643,"2026-06-09T23:02:38",64,"Жив",29484,null],[36644,"2026-06-09T23:02:39",64,"Стойте",29484,null],[36645,"2026-06-09T23:02:40",64,"Рано",29484,null],[36646,"2026-06-09T23:02:53",64,"Вы сняли половину+",29484,null],[36651,"2026-06-09T23:03:55",64,"ты звонко бьёшь его по голове алебардой со всей мочи, удар ломает его шлем на затылке, огр чуть наклоняется вперед от удара, а после разворачивается к тебе... Ход огра",29484,null],[36653,"2026-06-09T23:04:08",5,"// кд 14",29484,null],[36656,"2026-06-09T23:04:17",64,"//ты впритык подходишь?",36653,null],[36658,"2026-06-09T23:04:23",5,"нет, 10 футов//",29484,null],[36663,"2026-06-09T23:04:36",64,"/окау он тогда подходит",29484,null],[36664,"2026-06-09T23:04:47",5,"// кью провоцируется",29484,null],[36666,"2026-06-09T23:05:14",64,"//а она отошла ж",36664,null],[36667,"2026-06-09T23:05:25",5,"// а лол",29484,null],[36668,"2026-06-09T23:05:31",5,"// за что окружение тогда было)",29484,null],[36669,"2026-06-09T23:05:36",36,"//могу заклом ебануть, но эт так не работает",36666,null],[36670,"2026-06-09T23:05:46",5,"// ну бей огром",29484,null],[36674,"2026-06-09T23:06:05",64,"Огр отходит назад... Лошадь Жакио легает его в ответ. Но тот устремляется к тебе, заносит меч и наносит удар \n—БАААМ!",29484,null],[36675,"2026-06-09T23:06:13",64,"//за лошадь",36668,null],[36676,"2026-06-09T23:06:18",64,"/roll@roll_bot 1d20",29484,null],[36678,"2026-06-09T23:06:29",64,"Огр промазал крч",29484,null],[36679,"2026-06-09T23:06:30",64,"Или",29484,null],[36680,"2026-06-09T23:06:32",64,"/roll@roll_bot",29484,null],[36682,"2026-06-09T23:06:36",36,"//а можешь урон от лошади?",36674,null],[36684,"2026-06-09T23:06:37",64,"Лошадь не круче",29484,null],[36685,"2026-06-09T23:06:41",64,"1д4",36682,null],[36686,"2026-06-09T23:06:46",64,"+2 вроде или 1",29484,null],[36688,"2026-06-09T23:06:57",36,"//так Ладна... Мой ход, да?",29484,null],[36689,"2026-06-09T23:06:59",64,"2д4+3",29484,null],[36690,"2026-06-09T23:07:02",64,"//да",36688,null],[36691,"2026-06-09T23:08:08",36,"Верхом на лошади Кью подъезжает к огру и со всей дури на скаку бьёт посохом ему по голове с размаху. Словно у неё бита в руках. Оставляя в голове огра вмятину от головы серебристого дракона\n\n//Пусть кинет спас",29484,null],[36692,"2026-06-09T23:08:24",64,"/roll@roll_bot",29484,null],[36695,"2026-06-09T23:08:31",64,"Круто че",29484,null],[36696,"2026-06-09T23:08:33",36,"/r +d20+6",29484,null],[36698,"2026-06-09T23:08:42",64,"17, прошёл",36693,null],[36699,"2026-06-09T23:08:46",36,"Уеба",36695,null],[36700,"2026-06-09T23:09:24",36,"/r d8+3+d6+d6",29484,null],[36702,"2026-06-09T23:09:33",36,"//ура.... Рак кубов...",36701,null],[36704,"2026-06-09T23:10:44",64,"Твой удар сильно злит огра и он рычит, будто того мало было, он явно очень зол. Ход Жакио",29484,null],[36705,"2026-06-09T23:10:48",64,"/roll@roll_bot",29484,null],[36707,"2026-06-09T23:10:50",64,"Арбалет",29484,null],[36708,"2026-06-09T23:11:00",64,"А у него кд как у личинки все ок",29484,null],[36709,"2026-06-09T23:11:21",64,"/roll@roll_bot 1d8+3",29484,null],[36711,"2026-06-09T23:11:26",64,"Ещё 10",29484,null],[36712,"2026-06-09T23:11:43",64,"@elsio28 добьешь? Твой",29484,null],[36713,"2026-06-09T23:12:01",5,"Минотавр наносит режущий удар, а затем ещё один древком.",29484,null],[36714,"2026-06-09T23:12:06",5,"/r +d20+6",29484,null],[36716,"2026-06-09T23:12:13",5,"/r d10+4+2",29484,null],[36719,"2026-06-09T23:12:33",5,"// урон",36717,null],[36720,"2026-06-09T23:13:32",64,"ты точным ударом алебардой добиваешь Великана. Опиши: как ты это делаешь?",36717,null],[36721,"2026-06-09T23:13:46",36,"//а... Серьёзно? Пиздец ..",36720,null],[36723,"2026-06-09T23:14:19",64,"//да я сам ахуел, вы его довольно быстро замесили для твари с около 60 хитов",36721,null],[36724,"2026-06-09T23:14:25",5,"Размашистый удар проходит прямо через шею, отсекая голову великана от плеч. Тело падает, а минотавр ловко хватает летящую вниз башку.",29484,null],[36725,"2026-06-09T23:14:41",5,"// магия хб",36723,null],[36726,"2026-06-09T23:16:27",64,"тело падает на земь. В его зубах ты замечаешь какую то брошьку... Магическая? Кто знает. А главное: он роняет свой здоровенный, профессионально сделаный, могучий меч на земь. В нужных руках это очень могучее оружие. Вход в пещеру свободен",36724,null],[36727,"2026-06-09T23:16:55",64,"//какая то брошь и здоровый меч огра, можете между собой поделить @Professor_3M653 @elsio28",29484,null],[36728,"2026-06-09T23:17:08",5,"// детали будут?",29484,null],[36729,"2026-06-09T23:17:27",64,"//детали чего подожди",36728,null],[36730,"2026-06-09T23:17:33",5,"// что за арты",29484,null],[36731,"2026-06-09T23:17:51",36,"//меч конечно вкусно, но мне не надо. Беру брошь",36727,null],[36732,"2026-06-09T23:18:08",5,"Бхагар вытирает пот с лица, подходит к лошади и закрепляет на боку отрубленную голову огра. Затем успокаивающе гладит лошадь.",29484,null],[36733,"2026-06-09T23:18:19",36,"//у меня не было ХБ...",36725,null],[36734,"2026-06-09T23:18:37",5,"// раса хб, драконья кара хб",36733,null],[36735,"2026-06-09T23:18:44",64,"//ну там",36730,null],[36736,"2026-06-09T23:19:05",36,"//драконья кара не совсем ХБ ибо она есть на ттг Клаб, а там все балансоное",36734,null],[36737,"2026-06-09T23:19:24",5,"// на днд су ясно написано, что это хб",36736,null],[36738,"2026-06-09T23:19:25",64,"// \"Меч огроборца\" - искусно сделанный меч, размером около 2х метров в длинну с довольно толстым лезвием. Эта громадина весит 65 фунтов и наносит 2д8+1 рубящего урона. Это оружие считается импровизированным оружием, чтоб использовать его, у персонажа должна быть сила 16 или выше. Он не добавляет свой бонус мастерства к броскам атаки этим оружием, если не владеет импровизированным оружием. Оружие так же имеет свойства большое и двуручное.\n\n\n//и брошь защиты, спакуха гайс, мне хард все штуки одобрил, все легализованно",29484,null],[36739,"2026-06-09T23:20:01",64,"//Брошь защиты [Brooch of shielding]\nDMG14\nDMG24\n\nЧудесный предмет, необычный (требуется настройка)\nРекомендованная стоимость: 101-500 зм\nПока вы носите эту брошь, вы обладаете сопротивлением урону силовым полем и иммунитетом к урону от заклинания волшебная стрела [magic missile].",29484,null],[36740,"2026-06-09T23:20:14",36,"- А проверить... Ладно...\n\nКью махнула на него рукой, надела ожерелье что забрала у огра пока то ещё валялось и направилась в пещеру\n\n- Ку Ку... Есть кто живой?",36732,null],[36741,"2026-06-09T23:20:28",36,"//днд Су скопление педиков",36737,null],[36742,"2026-06-09T23:20:31",64,"//монетки вам не дам и так жирно там 100 от гоблинов",36739,null],[36743,"2026-06-09T23:20:54",36,"//о! Ебанная волшебная стрела\nПригодится в жизни наверная",36739,null],[36744,"2026-06-09T23:21:26",5,"// ладно, возьму меч",29484,null],[36745,"2026-06-09T23:21:31",5,"// а какая цена у него?",29484,null],[36746,"2026-06-09T23:21:41",5,"Минотавр идёт следом в пещеру",29484,null],[36747,"2026-06-09T23:22:39",64,"Кью входит в пещеру... Уютный домик огра, на костре варится котёл, в углу урна какая то с костями глубокая. Куча людского интерьера подбитого, ну, ошметки его и оторванная голова купца красиво лежит на полочке и уже неплохо так подгнивает. В пещере в основном мусор, так что смысла искать что то нет",36740,null],[36748,"2026-06-09T23:23:06",64,"//он необычный вообще, но хуй знает",36745,null],[36749,"2026-06-09T23:24:31",64,"//забирайте голову, едьте назад и я награды даю итоговые",29484,null],[36750,"2026-06-09T23:24:39",36,"- М-да... Жаль бедолагу...\n\nГоворит Кью достав голову купца с полки\n\n- Мешок есть? С собой возьмём. Покажем",36747,null],[36751,"2026-06-09T23:24:58",64,"//на пояс закрепите как кратос",36750,null],[36752,"2026-06-09T23:25:05",36,"//зачем продавать? Пользуйся, хороший же меч",36745,null],[36753,"2026-06-09T23:25:43",36,"Кью не дождавшись ответа пожала колесами, закрепила на поясе и ушла. Затем села на свою поняшку\n\n- Так... Одна умерла...",36751,null],[36754,"2026-06-09T23:25:45",64,"//у него персонаж на алебарды вообще ориентирован по идеи",36752,null],[36756,"2026-06-09T23:26:09",64,"//Чудище отдельно, дикари отдельно",36753,null],[36757,"2026-06-09T23:26:18",64,"//все, там кто кого куда относит",29484,null],[36758,"2026-06-09T23:28:24",5,"// да",36754,null],[36759,"2026-06-09T23:28:35",5,"ну один раунд ударить и бросить пойдёт//",29484,null],[36760,"2026-06-09T23:28:53",5,"Минотавр покачал головой и вернулся к лошади",29484,null],[36761,"2026-06-09T23:29:40",5,"// у меня ещё голова огра на лошади",29484,null],[36762,"2026-06-09T23:33:18",36,"Я достала верёвку и привязала чёрта к лошади минотавра с помощью веревки. А после поскакала вперёд, туда куда нада",36757,null],[36763,"2026-06-09T23:33:41",5,"// зачем...",36762,null],[36764,"2026-06-09T23:34:15",5,"Бхагар осторожно посадил чёрта сзади себя и они вместе поехали в деревню.",29484,null],[36765,"2026-06-09T23:36:49",36,"//да ну бля....",36764,null],[36766,"2026-06-09T23:37:02",36,"//да заебал просто... Он же обещал прицти",36763,null],[36767,"2026-06-09T23:37:20",36,"//сначала куда? Или по старому маршруту?",29484,null],[36769,"2026-06-09T23:39:06",64,"//да сразу конец квеста, все, там, ну можем ласт сценку отыграть пока я лут спрашиваю и потом кину, поделите нормально",36767,null],[36770,"2026-06-09T23:40:34",5,"// я могу им бить как обычно? типа я варвар, умения есть на всё",36738,null],[36771,"2026-06-09T23:40:40",36,"Черту нихуя, нам всё",36769,null],[36772,"2026-06-09T23:40:50",5,"// справедливо",36771,null],[36773,"2026-06-09T23:40:53",36,"//Владение",36770,null],[36774,"2026-06-09T23:41:07",36,"//и да, варвар владеет всеми видами оружия",29484,null],[36775,"2026-06-09T23:41:14",36,"//и простыми и воинскими",29484,null],[36776,"2026-06-09T23:41:24",36,"//хз входят ли туда огнестрел и дальнее",29484,null],[36777,"2026-06-09T23:42:00",64,"//ну там, бля тебе бы личный квест дать где ты им учишься владеть 🤔🤔🤔 вообще можешь бить, но там +3 всего на попадание будет, за то на урон сверху +2 вроде бы",36770,null],[36778,"2026-06-09T23:42:17",5,"// я же владею и так? это воинское",36777,null],[36779,"2026-06-09T23:42:21",64,"//ну он тоже побыл чучут, а обделять чёт",36771,null],[36780,"2026-06-09T23:43:11",36,"//его не было в боевках",36779,null],[36781,"2026-06-09T23:43:12",64,"//брат это импровизированное оружие, там черта есть дающая владение либо хз, там в угоду баланса я бы не разрешил такой штукой хуярить спокойно... А лан похуй, ебашь щас поменяю",36778,null],[36782,"2026-06-09T23:43:21",36,"//как минимум за боевки обделим",29484,null],[36783,"2026-06-09T23:43:56",64,"итоговые награды... \n\nТакс, было всего 2 боевые сцены с битвой и 1 которую смогли избежать\n\nИ за социалку которую делали, нарратив, за допросы получают ещё опыт @elsio28 и @Professor_3M653, итого \n\n230 за битвы+20 за аура фарминг+300 за завершение квеста=+550—Жакио\n385 за битвы+50 за социалку и общий вайб+300 за завершение=+735—Бхагар\n395 за битвы+55 за социалку и отыгрыш+300 за завершение квеста=+750—Кью\n\nДенежные награды:\nВ общем 100 зм с гоблинов копейками и ещё 50 за выполнение квеста\n\nНаграды лута:\n\nМеч огроборца на 2д8\nБрошь защиты\n\nС гоблинов вы получили:\n4 скимитара -1\n2 коротких лука -1 \nи 15 стрел\n\n@elsio28 @Professor_3M653 @Jak_Zak",29484,null],[36784,"2026-06-09T23:44:15",64,"Я больше скажу, он просто вроде в двух-трех сценах побыл, бэ",36782,null],[36785,"2026-06-09T23:44:18",36,"//мне жутко интересно как это тащит он и лошадь",36738,null],[36786,"2026-06-09T23:44:52",5,"и чёрта",36785,null],[36787,"2026-06-09T23:44:53",64,"//потому нужна сила +3",36785,null],[36788,"2026-06-09T23:44:59",5,"у меня +4",29484,null],[36789,"2026-06-09T23:45:20",64,"\"Меч огроборца\" \nНеобычный маг. Предмет (оружие) Цена: 101-500\n искусно сделанный меч, размером около 2х метров в длинну с довольно толстым лезвием. Эта громадина весит 65 фунтов и наносит 2д8+1 рубящего урона. Это оружие считается импровизированным оружием, чтоб использовать его, у персонажа должна быть сила 16 или выше. Оружие так же имеет свойства большое и двуручное.",29484,null],[36790,"2026-06-09T23:45:27",64,"//вообще пиздато",36788,null],[36791,"2026-06-09T23:45:36",64,"//ммм, ну и брошь защиты кидал там",29484,null],[36792,"2026-06-09T23:46:15",5,"// скимитары и луки продаем сразу?",29484,null],[36793,"2026-06-09T23:46:16",64,"Чувствую мне пизды дать могут но похуй, вроде более менее заслужено",29484,null],[36794,"2026-06-09T23:46:31",36,"//скимитары мои",36792,null],[36795,"2026-06-09T23:46:34",64,"В чистом виде в инвентарь заносите и там позже продаёте",36792,null],[36796,"2026-06-09T23:46:34",5,"// необычное? мне цена нужна",36789,null],[36797,"2026-06-09T23:46:38",36,"//остальное сам разберай",29484,null],[36798,"2026-06-09T23:46:46",64,"//101-500",36796,null],[36799,"2026-06-09T23:46:47",5,"// те 3 скимитара",36794,null],[36800,"2026-06-09T23:46:52",5,"// мне скимитар и луки",29484,null],[36801,"2026-06-09T23:47:03",36,"//дохуя чот",36800,null],[36802,"2026-06-09T23:47:10",5,"цена равная",29484,null],[36803,"2026-06-09T23:47:12",36,"//учитывая что я 3 гоблинов вольнула",29484,null],[36804,"2026-06-09T23:47:13",64,"Все",36789,null],[36805,"2026-06-09T23:47:39",64,"//вы по опыту с той битвы равные ушли",36803,null],[36806,"2026-06-09T23:47:42",36,"//надо было Варга тебе освежевать и его шкуру продать",36802,null],[36807,"2026-06-09T23:48:04",5,"я ещё себе запишу голову огра как трофей чисто",29484,null],[36808,"2026-06-09T23:48:08",5,"косметический",29484,null],[36809,"2026-06-09T23:48:34",64,"Справедливости ради, пусть и не сам, он треть огра забрал",36783,null],[36810,"2026-06-09T23:48:46",5,"надо и ему что-то дать",29484,null],[36811,"2026-06-09T23:48:54",64,"Деньги поделите там",36810,null],[36812,"2026-06-09T23:49:03",64,"60 60 и 30",29484,null],[36813,"2026-06-09T23:49:04",36,"//я же правильно понимаю что 150 за это на троих?",36783,null],[36814,"2026-06-09T23:49:18",64,"Да",36813,null],[36815,"2026-06-09T23:49:27",36,"Ну... Можно и так",36812,null],[36816,"2026-06-09T23:49:40",5,"норм",36812,null],[36817,"2026-06-09T23:51:11",5,"а стрелы кому нужны?",29484,null],[36818,"2026-06-09T23:51:22",5,"го стрелы чёрту",29484,null],[36819,"2026-06-09T23:51:27",5,"он стрелял как раз",29484,null],[36820,"2026-06-09T23:51:46",64,"Болтами*",36819,null],[36821,"2026-06-09T23:51:48",64,"Кхе",29484,null],[36822,"2026-06-09T23:51:56",5,"ну пусть превращает",29484,null],[36825,"2026-06-10T00:04:10",36,"Что могу сказать о квесте?\n\nДля первого раза очень даже не плохо, в частности боевки. Обычно там у всех запары, но не здесь. В плане социальки не хватает порядка (хотя у меня такое тоже бывает, каюсь) сама игра была довольно интересной и концовка была не очень банальной.",29484,null],[36826,"2026-06-10T00:07:57",64,"//у меня стаж игр года 2 может уже 🚬🚬🚬🚬🚬 прост в социалки не умею, никогда не показывали как обычно в социалки играть и не понимаю до сих пор как их делать нормально. Спасибо за отзыв в любом случае🌹",36825,null],[36827,"2026-06-10T00:11:13",5,"Мне понравилась социалка, хоть и очень короткая. Не понравилось, что для прогресса в квесте надо \"всего лишь\" 3 раза подряд пройти проверку выживания. Хотелось бы больше нарратива в этом плане, а не всё по броскам кубика.",29484,null],[36828,"2026-06-10T00:12:47",64,"//теж спасибо за отзыв🌹\nУ меня на опыте обычно кубами все делали и механику считай на ходу додумал, в любом случае спасибо за критику, исправимся",36827,null]]);
